@pytest.fixture(scope="module", autouse=True)
def isolated_formal_source_trust_root(
    tmp_path_factory: pytest.TempPathFactory,
) -> Any:
    """Every formal-source test uses a fresh tmp trust root and ledger."""
    import tripchord.formal_live_source as formal_source

    global _TEST_FORMAL_CONTROL_TOKEN_PATH
    global _TEST_FORMAL_LEDGER_PATH
    global _TEST_FORMAL_PRIVATE_KEY_PATH
    global _TEST_FORMAL_PUBLIC_KEY_DER

    root = tmp_path_factory.mktemp("formal-source-trust-parent") / "trust"
    original_root = os.environ.get("TRIPCHORD_FORMAL_SOURCE_TRUST_ROOT")
    provisioned = formal_source.provision_formal_source_trust_root(root)
    os.environ["TRIPCHORD_FORMAL_SOURCE_TRUST_ROOT"] = str(root)
    generation = str(provisioned["generation"])
    private_path = root / generation / "authority-private.pem"
    control_path = root / "control-token"
    public_der = formal_source._load_verification_anchor(root)["public_key_der"]
    assert isinstance(public_der, bytes)
    _TEST_FORMAL_PRIVATE_KEY_PATH = private_path
    _TEST_FORMAL_LEDGER_PATH = root / "ledger.json"
    _TEST_FORMAL_CONTROL_TOKEN_PATH = control_path
    _TEST_FORMAL_PUBLIC_KEY_DER = public_der
    try:
        yield
    finally:
        if original_root is None:
            os.environ.pop("TRIPCHORD_FORMAL_SOURCE_TRUST_ROOT", None)
        else:
            os.environ["TRIPCHORD_FORMAL_SOURCE_TRUST_ROOT"] = original_root


def _init_git_repo(root: Path) -> None:
    subprocess.run(["git", "init", "-q", str(root)], check=True)
    subprocess.run(
        ["git", "-C", str(root), "config", "user.email", "gate-test@example.com"],
        check=True,
    )
    subprocess.run(
        ["git", "-C", str(root), "config", "user.name", "Gate Test"],
        check=True,
    )
    tracked = root / "tracked.txt"
    tracked.write_text("baseline\n", encoding="utf-8")
    subprocess.run(["git", "-C", str(root), "add", "tracked.txt"], check=True)
    subprocess.run(
        ["git", "-C", str(root), "commit", "-q", "-m", "baseline"],
        check=True,
    )


@pytest.fixture()
def clean_repo(tmp_path: Path) -> Path:
    repo = tmp_path / "repo"
    _init_git_repo(repo)
    return repo


@pytest.fixture()
def staging_dir(tmp_path: Path) -> Path:
    # A sibling of the repo root, so an in-repo untracked dir never pollutes
    # the git status the gate snapshots.
    return tmp_path / "staging"


def _head(root: Path) -> str:
    out = subprocess.run(
        ["git", "-C", str(root), "rev-parse", "HEAD"],
        capture_output=True,
        text=True,
        check=True,
    )
    return out.stdout.strip()


def _patch_root(monkeypatch: pytest.MonkeyPatch, root: Path) -> None:
    monkeypatch.setattr(gate, "ROOT", root)
    monkeypatch.setattr(gate, "RESULTS_DIR", root / "benchmarks" / "results")


def _passing_layers(monkeypatch: pytest.MonkeyPatch) -> None:
    for attr, layer_name in (
        ("layer1_reproducibility", "1_reproducibility"),
        ("layer2_replay", "2_replay"),
        ("layer3_clean_chrome_fixtures", "3_clean_chrome_fixtures"),
        ("layer4_model_smoke", "4_model_smoke"),
        ("layer5_real_canary", "5_real_canary"),
        ("layer6_full_e2e", "6_full_e2e"),
    ):
        monkeypatch.setattr(
            gate,
            attr,
            lambda *args, layer_name=layer_name, **kwargs: gate.LayerResult(
                name=layer_name, passed=True
            ),
        )


def _populating_passing_layers(
    monkeypatch: pytest.MonkeyPatch, staging_dir: Path
) -> None:
    """Mock every layer to pass AND write the raw required evidence into staging,
    modelling the real flow (C-114 R3): main() creates an initially-empty staging
    dir, then the layers populate it — the tests never hand main() a pre-filled
    dir, because the gate refuses reused non-empty staging."""
    # A real runtime always has a persisted bridge-state file (docs/operations.md
    # pins TRIPCHORD_BROWSER_BRIDGE_STATE_PATH); simulate it so the layer-6
    # compact's bridge_state_lease_preflight binding carries a valid sha256
    # (C-122 Fix 2).  The file lives out-of-repo so it never dirties porcelain.
    bridge_state_path = staging_dir.parent / "bridge-state.json"
    bridge_state_path.write_text(
        json.dumps(
            {
                "schema_version": "tripchord-browser-bridge-state-v2",
                "saved_at": "2026-08-10T00:00:00+00:00",
                "tasks": [],
                "reload_requests": [],
            }
        ),
        encoding="utf-8",
    )
    monkeypatch.setenv(gate._BRIDGE_STATE_ENV, str(bridge_state_path))
    monkeypatch.setattr(gate, "_new_run_id", lambda: _TEST_RUN_ID)
    monkeypatch.setattr(
        gate,
        "layer1_reproducibility",
        lambda *args, sd=staging_dir: (
            _populate_required_evidence(sd, run_id=_TEST_RUN_ID),
            gate.LayerResult(name="1_reproducibility", passed=True),
        )[1],
    )
    for attr, layer_name in (
        ("layer2_replay", "2_replay"),
        ("layer3_clean_chrome_fixtures", "3_clean_chrome_fixtures"),
        ("layer4_model_smoke", "4_model_smoke"),
        ("layer5_real_canary", "5_real_canary"),
        ("layer6_full_e2e", "6_full_e2e"),
    ):
        monkeypatch.setattr(
            gate,
            attr,
            lambda *args, layer_name=layer_name, **kwargs: gate.LayerResult(
                name=layer_name, passed=True
            ),
        )


def _populating_passing_layers_without(
    monkeypatch: pytest.MonkeyPatch, staging_dir: Path, *missing_names: str
) -> None:
    """Like ``_populating_passing_layers`` but a set of required evidence inputs
    is removed AFTER the layers write them, modelling a run that never produced
    those inputs (C-118: evidence-contract counter-examples)."""

    def layer1(
        *args: object,
        sd: Path = staging_dir,
        names: tuple[str, ...] = missing_names,
    ) -> gate.LayerResult:
        _populate_required_evidence(sd, run_id=_TEST_RUN_ID)
        for name in names:
            (sd / name).unlink(missing_ok=True)
        return gate.LayerResult(name="1_reproducibility", passed=True)

    monkeypatch.setattr(gate, "_new_run_id", lambda: _TEST_RUN_ID)
    monkeypatch.setattr(gate, "layer1_reproducibility", layer1)
    for attr, layer_name in (
        ("layer2_replay", "2_replay"),
        ("layer3_clean_chrome_fixtures", "3_clean_chrome_fixtures"),
        ("layer4_model_smoke", "4_model_smoke"),
        ("layer5_real_canary", "5_real_canary"),
        ("layer6_full_e2e", "6_full_e2e"),
    ):
        monkeypatch.setattr(
            gate,
            attr,
            lambda *args, layer_name=layer_name, **kwargs: gate.LayerResult(
                name=layer_name, passed=True
            ),
        )


def _fixture_formal_source_binding(
    commit_sha: str = "a" * 40,
    *,
    run_id: str = "fixture-formal-run",
    install_id: str = "00000000-0000-4000-8000-000000000001",
    authority_secret: str | None = None,
    trust: bool = True,
) -> dict[str, object]:
    """Valid compact receipt chain for unit tests of unrelated gate behavior.

    The formal end-to-end positive never uses this synthetic helper; it reads
    the binding emitted by the production composition and transport boundaries.
    """
    return _strict_fixture_formal_source_binding(
        commit_sha=commit_sha,
        run_id=run_id,
        install_id=install_id,
        authority_secret=authority_secret,
        trust=trust,
    )

    # Historical pre-v3 fixture remains below for forensic comparison only.
    import base64

    from cryptography.hazmat.primitives import serialization
    from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey
    from tripchord.formal_live_source import (
        _BINDING_SCHEMA_VERSION,
        _CHALLENGE_SCHEMA_VERSION,
        _RECEIPT_SCHEMA_VERSION,
        _anchor_version,
        _authority_key_id,
        _challenge_proof_payload,
        _receipt_proof_payload,
        formal_composition_contract,
        validate_formal_source_binding,
    )

    composition = formal_composition_contract(commit_sha)

    def digest(value: object) -> str:
        return hashlib.sha256(
            json.dumps(
                value,
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            ).encode("utf-8")
        ).hexdigest()

    composition_sha256 = digest(
        {"install_id": install_id, "composition": composition}
    )
    if trust:
        assert _TEST_FORMAL_PRIVATE_KEY_PATH is not None
        loaded = serialization.load_pem_private_key(
            _TEST_FORMAL_PRIVATE_KEY_PATH.read_bytes(),
            password=None,
        )
        assert isinstance(loaded, Ed25519PrivateKey)
        private_key = loaded
    else:
        seed = hashlib.sha256(
            (authority_secret or "foreign-formal-source-authority").encode()
        ).digest()
        private_key = Ed25519PrivateKey.from_private_bytes(seed)

    def sign(value: object) -> str:
        raw = json.dumps(
            value,
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        ).encode()
        return base64.b64encode(private_key.sign(raw)).decode()

    runtime_identity = {
        "pid": 1,
        "started_at": "2026-08-10T00:00:00+00:00",
        "repo_toplevel": "/repo",
        "commit_sha": commit_sha,
        "dependency_lock_sha256": "d" * 64,
        "live_system_source_sha256": "e" * 64,
        "python_version": "3.12.0",
        "python_executable": "/usr/bin/python3",
    }
    challenge: dict[str, object] = {
        "schema_version": _CHALLENGE_SCHEMA_VERSION,
        "anchor_version": _anchor_version(),
        "authority_key_id": _authority_key_id(),
        "challenge_id": "10000000-0000-4000-8000-000000000001",
        "nonce_digest": "f" * 64,
        "run_id": run_id,
        "tested_commit_sha": commit_sha,
        "runtime_identity": runtime_identity,
        "request_sha256": "f" * 64,
        "candidate_set_sha256": "a" * 64,
        "scenario_sha256": "a" * 64,
        "issued_at": "2026-08-10T00:00:00+00:00",
        "expires_at": "2026-08-10T01:00:00+00:00",
    }
    challenge["signature"] = sign(_challenge_proof_payload(challenge))
    previous = composition_sha256
    events: list[dict[str, object]] = []
    rows = (
        (
            "browser_heartbeat",
            "POST",
            "/browser-bridge/v1/companions/heartbeat",
            ["comp-1"],
            None,
        ),
        (
            "browser_claim",
            "POST",
            "/browser-bridge/v1/tasks/claim",
            ["task-1"],
            None,
        ),
        (
            "browser_complete",
            "POST",
            "/browser-bridge/v1/tasks/{task_id}/complete",
            ["task-1"],
            None,
        ),
        (
            "icom_public_get",
            "GET",
            "/api/v1/public/trips/schedules",
            [],
            "1" * 64,
        ),
        (
            "icom_public_get",
            "GET",
            "/api/v1/public/ferry-fares/schedule-base-price",
            [],
            "2" * 64,
        ),
        (
            "icom_public_get",
            "GET",
            "/api/v1/public/policy-sections",
            [],
            "3" * 64,
        ),
    )
    for sequence, (kind, method, path, subject_ids, response_sha256) in enumerate(
        rows, start=1
    ):
        companion_identity = {
            "companion_id": "comp-1",
            "providers": ["ctrip", "qunar", "tongcheng"],
            "authorized_scope_keys": sorted(gate._CERTIFIED_OTA_SCOPES),
            "adapter_version": "0.2.0",
            "contract_version": "tripchord-capability-v1",
            "runtime_instance_id": "fixture-runtime-instance-0001",
        }
        query_identity = {
            "origin": "HGH",
            "destination": "MLE",
            "start_date": "2026-08-23",
            "end_date": "2026-08-30",
            "adults": 1,
            "rooms": 1,
            "currency": "CNY",
            "origin_code": "HGH",
            "destination_code": "MLE",
            "search_url": None,
            "options": {},
        }
        if kind == "browser_heartbeat":
            details = {
                "request": companion_identity,
                "heartbeat": {
                    **companion_identity,
                    "last_seen": "2026-08-10T00:00:01+00:00",
                    "age_seconds": 0.0,
                    "is_fresh": True,
                    "build_identity": {
                        "protocol_version": "tripchord-companion-control-v1",
                        "manifest_version": "1.0.0",
                        "build_sha256": "9" * 64,
                        "content_runtime_version": "1.0.0",
                    },
                },
            }
        elif kind == "browser_claim":
            details = {
                "request": {
                    **companion_identity,
                    "limit": 6,
                    "build_identity": {
                        "protocol_version": "tripchord-companion-control-v1",
                        "manifest_version": "1.0.0",
                        "build_sha256": "9" * 64,
                        "content_runtime_version": "1.0.0",
                    },
                },
                "leases": [
                    {
                        "task_id": "task-1",
                        "provider": "ctrip",
                        "kind": "flight",
                        "query": query_identity,
                        "timeout_seconds": 30,
                        "claimed_at": "2026-08-10T00:00:02+00:00",
                        "lease_expires_at": "2026-08-10T00:00:32+00:00",
                    }
                ],
            }
        elif kind == "browser_complete":
            quotes = [
                {
                    "provider": "ctrip",
                    "kind": "flight",
                    "page_url": "https://flights.ctrip.com/online/list/oneway-hgh-mle",
                    "captured_at": "2026-08-10T00:00:03+00:00",
                    "parser_version": "fixture-v1",
                    "visible_evidence": "fixture visible result",
                    "evidence_sha256": "8" * 64,
                    "currency": "CNY",
                    "amount": "100.00",
                    "price_basis": "per_person",
                    "taxes_included": True,
                    "title": "fixture flight",
                    "details": {},
                }
            ]
            snapshot = {
                "id": "task-1",
                "provider": "ctrip",
                "kind": "flight",
                "query": query_identity,
                "state": "succeeded",
                "created_at": "2026-08-10T00:00:01+00:00",
                "updated_at": "2026-08-10T00:00:03+00:00",
                "attempt_count": 1,
                "claimed_by": "comp-1",
                "claimed_at": "2026-08-10T00:00:02+00:00",
                "quotes": quotes,
                "failure": None,
                "reused_from_task_id": None,
                "reuse_age_seconds": None,
                "inflight_coalesced": False,
            }
            details = {
                "task_id": "task-1",
                "completion": {
                    "state": "succeeded",
                    "quotes": quotes,
                    "failure": None,
                },
                "snapshot": snapshot,
                "result_sha256": digest(snapshot),
            }
        else:
            query = (
                {"date": "2026-08-23"}
                if path == "/api/v1/public/trips/schedules"
                else {}
            )
            suffix = f"?date={query['date']}" if query else ""
            details = {
                "query_task_id": "public-transfer-icom-continuous-outbound",
                "query_identity": {
                    "travel_date": "2026-08-23",
                    "origin": "Airport",
                    "destination": "Maafushi",
                    "adults": 1,
                },
                "url": f"https://sfs-api.icomtours.com{path}{suffix}",
                "path": path,
                "query": query,
                "travel_date": query.get("date"),
                "captured_at": f"2026-08-10T00:00:0{sequence}+00:00",
                "raw_response_sha256": response_sha256,
                "normalized_evidence_sha256": str(sequence) * 64,
            }
        event: dict[str, object] = {
            "sequence": sequence,
            "kind": kind,
            "method": method,
            "path": path,
            "subject_ids": subject_ids,
            "details": details,
            "response_sha256": response_sha256,
            "observed_at": f"2026-08-10T00:00:0{sequence}+00:00",
            "challenge_id": challenge["challenge_id"],
            "nonce_digest": challenge["nonce_digest"],
            "context": {
                **{
                    key: challenge[key]
                    for key in (
                        "run_id",
                        "tested_commit_sha",
                        "runtime_identity",
                        "request_sha256",
                        "candidate_set_sha256",
                        "scenario_sha256",
                    )
                },
                "challenge_id": challenge["challenge_id"],
                "nonce_digest": challenge["nonce_digest"],
                "install_id": install_id,
                "composition_sha256": composition_sha256,
            },
            "previous_receipt_sha256": previous,
        }
        event["receipt_sha256"] = digest(event)
        event["signature"] = sign(
            {
                "purpose": "tripchord-formal-live-source-event-v3",
                "receipt_sha256": event["receipt_sha256"],
            }
        )
        previous = str(event["receipt_sha256"])
        events.append(event)
    binding = {
        "schema_version": _BINDING_SCHEMA_VERSION,
        "anchor_version": _anchor_version(),
        "install_id": install_id,
        "composition": composition,
        "composition_sha256": composition_sha256,
        "authority_key_id": _authority_key_id(),
        "runtime_identity": runtime_identity,
        "challenge": challenge,
        "pre_event_count": 0,
        "pre_chain_sha256": composition_sha256,
        "post_event_count": len(events),
        "post_chain_sha256": events[-1]["receipt_sha256"],
        "companion_heartbeat_receipt": events[0],
        "receipts": events,
    }
    binding["binding_digest"] = digest(binding)
    authority_receipt: dict[str, object] = {
        "schema_version": _RECEIPT_SCHEMA_VERSION,
        "anchor_version": _anchor_version(),
        "authority_key_id": _authority_key_id(),
        "challenge_id": challenge["challenge_id"],
        "nonce_digest": challenge["nonce_digest"],
        "binding_digest": binding["binding_digest"],
        "run_id": challenge["run_id"],
        "tested_commit_sha": commit_sha,
        "runtime_identity": runtime_identity,
        "pre_event_count": 0,
        "post_event_count": len(events),
        "delta_digest": digest(events),
        "issued_at": challenge["issued_at"],
        "verified_at": "2026-08-10T00:00:07+00:00",
    }
    authority_receipt["signature"] = sign(
        _receipt_proof_payload(authority_receipt)
    )
    binding["authority_receipt"] = authority_receipt
    if not trust:
        return binding
    return validate_formal_source_binding(binding)


def _strict_fixture_formal_source_binding(
    *,
    commit_sha: str,
    run_id: str,
    install_id: str,
    authority_secret: str | None,
    trust: bool,
) -> dict[str, object]:
    import base64

    from cryptography.hazmat.primitives import serialization
    from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey
    from tripchord.agents.stay_area import system_stay_area_search_profile
    from tripchord.formal_live_source import (
        _BINDING_SCHEMA_VERSION,
        _CHALLENGE_CONTEXT_FIELDS,
        _CHALLENGE_SCHEMA_VERSION,
        _RECEIPT_SCHEMA_VERSION,
        _anchor_version,
        _authority_key_id,
        _challenge_proof_payload,
        _job_member_summary,
        _receipt_proof_payload,
        formal_composition_contract,
        formal_job_graph_for_frozen_v4,
    )
    from tripchord.planning.stay_plans import system_stay_plan_candidate_set
    from tripchord.providers.browser_bridge import (
        BrowserSearchQuery,
        ctrip_trusted_flight_search_url,
        qunar_trusted_flight_search_url,
        tongcheng_trusted_flight_search_url,
    )

    def digest(value: object) -> str:
        return hashlib.sha256(
            json.dumps(
                value,
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            ).encode()
        ).hexdigest()

    assert _TEST_FORMAL_PRIVATE_KEY_PATH is not None
    if trust:
        loaded = serialization.load_pem_private_key(
            _TEST_FORMAL_PRIVATE_KEY_PATH.read_bytes(), password=None
        )
        assert isinstance(loaded, Ed25519PrivateKey)
        private_key = loaded
        anchor_version = _anchor_version()
        authority_key_id = _authority_key_id()
    else:
        private_key = Ed25519PrivateKey.from_private_bytes(
            hashlib.sha256(
                (authority_secret or "foreign-formal-source-authority").encode()
            ).digest()
        )
        public_der = private_key.public_key().public_bytes(
            serialization.Encoding.DER,
            serialization.PublicFormat.SubjectPublicKeyInfo,
        )
        anchor_version = "tripchord-formal-source-anchor-v2:foreign"
        authority_key_id = hashlib.sha256(public_der).hexdigest()

    def sign(value: object) -> str:
        return base64.b64encode(
            private_key.sign(
                json.dumps(
                    value,
                    ensure_ascii=False,
                    separators=(",", ":"),
                    sort_keys=True,
                ).encode()
            )
        ).decode()

    composition = formal_composition_contract(commit_sha)
    composition_sha256 = digest(
        {"install_id": install_id, "composition": composition}
    )
    runtime_identity = {
        "pid": 1,
        "started_at": "2026-08-10T00:00:00+00:00",
        "repo_toplevel": "/repo",
        "commit_sha": commit_sha,
        "dependency_lock_sha256": "d" * 64,
        "live_system_source_sha256": "e" * 64,
        "python_version": "3.12.0",
        "python_executable": "/usr/bin/python3",
    }
    job_graph = formal_job_graph_for_frozen_v4(
        terminal_job_id="live-job-fixture",
        request_sha256="f" * 64,
        adults=2,
    )
    stay_plan_candidate_set = system_stay_plan_candidate_set().model_dump(
        mode="json"
    )
    stay_area_search_profile = system_stay_area_search_profile("马累")
    assert stay_area_search_profile is not None
    stay_area_payload = stay_area_search_profile.model_dump(mode="json")
    challenge: dict[str, object] = {
        "schema_version": _CHALLENGE_SCHEMA_VERSION,
        "anchor_version": anchor_version,
        "authority_key_id": authority_key_id,
        "challenge_id": "10000000-0000-4000-8000-000000000001",
        "nonce_digest": "f" * 64,
        "run_id": run_id,
        "tested_commit_sha": commit_sha,
        "runtime_identity": runtime_identity,
        "request_sha256": "f" * 64,
        "candidate_set_sha256": stay_plan_candidate_set[
            "candidate_set_sha256"
        ],
        "scenario_sha256": "a" * 64,
        "job_graph": job_graph,
        "issued_at": "2026-08-10T00:00:00+00:00",
        "expires_at": "2026-08-10T01:00:00+00:00",
    }
    challenge["signature"] = sign(_challenge_proof_payload(challenge))
    previous = composition_sha256
    events: list[dict[str, object]] = []
    base_time = datetime(2026, 8, 10, tzinfo=UTC)

    def add_event(
        kind: str,
        method: str,
        path: str,
        subject_ids: list[str],
        details: dict[str, object],
        response_sha256: str | None = None,
    ) -> None:
        nonlocal previous
        sequence = len(events) + 1
        event: dict[str, object] = {
            "sequence": sequence,
            "kind": kind,
            "method": method,
            "path": path,
            "subject_ids": subject_ids,
            "details": details,
            "response_sha256": response_sha256,
            "observed_at": (base_time + timedelta(seconds=sequence)).isoformat(),
            "challenge_id": challenge["challenge_id"],
            "nonce_digest": challenge["nonce_digest"],
            "context": {
                **{
                    key: challenge[key]
                    for key in _CHALLENGE_CONTEXT_FIELDS - {"job_graph"}
                },
                "job_graph_sha256": job_graph["job_graph_sha256"],
                "challenge_id": challenge["challenge_id"],
                "nonce_digest": challenge["nonce_digest"],
                "install_id": install_id,
                "composition_sha256": composition_sha256,
            },
            "previous_receipt_sha256": previous,
        }
        event["receipt_sha256"] = digest(event)
        event["signature"] = sign(
            {
                "purpose": "tripchord-formal-live-source-event-v3",
                "receipt_sha256": event["receipt_sha256"],
            }
        )
        previous = str(event["receipt_sha256"])
        events.append(event)

    build_identity = {
        "protocol_version": "tripchord-companion-control-v1",
        "manifest_version": "1.0.0",
        "build_sha256": "9" * 64,
        "content_runtime_version": "1.0.0",
    }
    companion = {
        "companion_id": "comp-1",
        "providers": ["ctrip", "qunar", "tongcheng"],
        "authorized_scope_keys": sorted(gate._CERTIFIED_OTA_SCOPES),
        "adapter_version": "0.2.0",
        "contract_version": "tripchord-capability-v1",
        "build_identity": build_identity,
        "runtime_instance_id": "fixture-runtime-instance-0001",
    }
    companion_identity_sha256 = digest(companion)
    add_event(
        "browser_heartbeat",
        "POST",
        "/browser-bridge/v1/companions/heartbeat",
        ["comp-1"],
        {
            "request": companion,
            "heartbeat": {
                **companion,
                "last_seen": (base_time + timedelta(seconds=1)).isoformat(),
                "age_seconds": 0.0,
                "is_fresh": True,
            },
            "companion_identity_sha256": companion_identity_sha256,
        },
    )

    query_sequence = 0
    for pair in job_graph["pairs"]:
        assert isinstance(pair, dict)
        departure = date.fromisoformat(str(pair["departure_date"]))
        returning = date.fromisoformat(str(pair["return_date"]))
        phase_members = [
            (query_task_id, "checkpoint_exploration")
            for query_task_id in pair["query_task_ids"]
        ] + [
            (query_task_id, "publication_refresh")
            for query_task_id in pair["publication_query_task_ids"]
        ]
        for query_task_id, execution_phase in phase_members:
            assert isinstance(query_task_id, str)
            query_sequence += 1
            _prefix, provider, query_kind, _task_digest = query_task_id.split(":")
            runtime_task_id = f"task-{query_sequence:02d}"
            if query_kind == "flight":
                kind, segment = "flight", None
                start, end, direction = departure, returning, "round_trip"
            else:
                kind, direction = "lodging", "stay"
                segment, start, end = {
                    "lodging_full_stay": ("full", departure, returning),
                    "lodging_first_night": (
                        "first",
                        departure,
                        departure + timedelta(days=1),
                    ),
                    "lodging_middle_stay": (
                        "middle",
                        departure + timedelta(days=1),
                        returning - timedelta(days=1),
                    ),
                    "lodging_last_night": (
                        "last",
                        returning - timedelta(days=1),
                        returning,
                    ),
                    "lodging_hulhumale_full_stay": (
                        "hulhumale-full",
                        departure,
                        returning,
                    ),
                }[query_kind]
            options: dict[str, object] = {
                "__tripchord_allow_recent_quote_reuse": (
                    execution_phase == "checkpoint_exploration"
                ),
                "gateway_destination": "马累",
                "stay_area_search_profile": stay_area_payload,
                "stay_plan_candidate_set": stay_plan_candidate_set,
            }
            if segment is not None:
                lodging_identity = {
                    "full": ("maafushi", "destination_island", "Maafushi"),
                    "middle": ("maafushi", "destination_island", "Maafushi"),
                    "first": ("hulhumale", "airport_island", "Hulhumalé"),
                    "last": ("hulhumale", "airport_island", "Hulhumalé"),
                    "hulhumale-full": (
                        "hulhumale",
                        "airport_island",
                        "Hulhumalé",
                    ),
                }[segment]
                options.update(
                    {
                        "segment": segment,
                        "expected_lodging_place_key": lodging_identity[0],
                        "expected_package_area": lodging_identity[1],
                    }
                )
                destination = lodging_identity[2]
                destination_code = None
            else:
                destination = "马累"
                destination_code = "MLE"
            query = {
                "origin": "杭州",
                "destination": destination,
                "start_date": start.isoformat(),
                "end_date": end.isoformat(),
                "adults": 2,
                "rooms": 1,
                "currency": "CNY",
                "origin_code": "HGH",
                "destination_code": destination_code,
                "search_url": None,
                "options": options,
            }
            if kind == "flight":
                typed_query = BrowserSearchQuery.model_validate(query)
                query["search_url"] = {
                    "ctrip": ctrip_trusted_flight_search_url,
                    "qunar": qunar_trusted_flight_search_url,
                    "tongcheng": tongcheng_trusted_flight_search_url,
                }[provider](typed_query)
            formal_query: dict[str, object] = {
                "terminal_job_id": job_graph["terminal_job_id"],
                "pair_id": pair["date_pair_id"],
                "task_id": runtime_task_id,
                "query_task_id": query_task_id,
                "provider": provider,
                "kind": kind,
                "query_kind": query_kind,
                "direction": direction,
                "start_date": start.isoformat(),
                "end_date": end.isoformat(),
                "query_sha256": digest(query),
                "execution_phase": execution_phase,
            }
            formal_query["query_identity"] = digest(formal_query)
            claimed_at = (
                base_time + timedelta(seconds=len(events) + 1)
            ).isoformat()
            add_event(
                "browser_claim",
                "POST",
                "/browser-bridge/v1/tasks/claim",
                [runtime_task_id],
                {
                    "request": {
                        **companion,
                        "limit": 1,
                        "build_identity": build_identity,
                    },
                    "leases": [
                        {
                            "task_id": runtime_task_id,
                            "provider": provider,
                            "kind": kind,
                            "query": query,
                            "timeout_seconds": 120,
                            "claimed_at": claimed_at,
                            "lease_expires_at": (
                                base_time + timedelta(seconds=len(events) + 121)
                            ).isoformat(),
                            "formal_query": formal_query,
                        }
                    ],
                },
            )
            quotes = [{"fixture": query_task_id}]
            snapshot = {
                "id": runtime_task_id,
                "provider": provider,
                "kind": kind,
                "query": query,
                "state": "succeeded",
                "created_at": claimed_at,
                "updated_at": (
                    base_time + timedelta(seconds=len(events) + 1)
                ).isoformat(),
                "attempt_count": 1,
                "claimed_by": "comp-1",
                "claimed_at": claimed_at,
                "quotes": quotes,
                "failure": None,
                "reused_from_task_id": None,
                "reuse_age_seconds": None,
                "inflight_coalesced": False,
            }
            completion = {
                "state": "succeeded",
                "quotes": quotes,
                "failure": None,
            }
            completed_at = (
                base_time + timedelta(seconds=len(events) + 1)
            ).isoformat()
            source_observation = {
                "task_id": runtime_task_id,
                "provider": provider,
                "kind": kind,
                "query": query,
                "quote_evidence_sha256": [
                    quote.get("evidence_sha256") for quote in quotes
                ],
                "parser_version": "tripchord-visible-dom-v3",
            }
            unsigned_source_receipt: dict[str, object] = {
                "schema_version": (
                    "tripchord-browser-source-execution-receipt-v1"
                ),
                "task_id": runtime_task_id,
                "provider": provider,
                "kind": kind,
                "companion_id": companion["companion_id"],
                "runtime_instance_id": companion["runtime_instance_id"],
                "build_identity": build_identity,
                "execution_environment": "chrome_extension_service_worker",
                "parser_version": "tripchord-visible-dom-v3",
                "query_sha256": digest(query),
                "source_observation_sha256": digest(source_observation),
                "completion_sha256": digest(completion),
                "capability_id": "20000000-0000-4000-8000-000000000001",
                "challenge_id": challenge["challenge_id"],
                "run_id": challenge["run_id"],
                "terminal_job_id": job_graph["terminal_job_id"],
                "request_sha256": job_graph["request_sha256"],
                "job_graph_sha256": job_graph["job_graph_sha256"],
                "attempt_digest": "7" * 64,
                "completed_at": completed_at,
            }
            source_execution_receipt = {
                **unsigned_source_receipt,
                "receipt_sha256": digest(unsigned_source_receipt),
            }
            add_event(
                "browser_complete",
                "POST",
                "/browser-bridge/v1/tasks/{task_id}/complete",
                [runtime_task_id],
                {
                    "task_id": runtime_task_id,
                    "completion": completion,
                    "source_execution_receipt": source_execution_receipt,
                    "snapshot": snapshot,
                    "formal_query": formal_query,
                    "result_sha256": digest(snapshot),
                },
            )

    for expected_query in (
        *job_graph["icom_queries"],
        *job_graph["publication_icom_queries"],
    ):
        assert isinstance(expected_query, dict)
        identity = {
            key: expected_query[key]
            for key in (
                "pair_id",
                "source_task_id",
                "query_task_id",
                "direction",
                "travel_date",
                "departure_date",
                "return_date",
                "origin",
                "destination",
                "adults",
            )
        }
        for endpoint_index, path in enumerate(
            (
                "/api/v1/public/trips/schedules",
                "/api/v1/public/ferry-fares/schedule-base-price",
                "/api/v1/public/policy-sections",
            ),
            start=1,
        ):
            query = {"date": expected_query["travel_date"]} if endpoint_index == 1 else {}
            suffix = f"?date={expected_query['travel_date']}" if query else ""
            call_id = f"{expected_query['query_task_id']}|{path}"
            response_sha = digest({"call_id": call_id})
            call_identity = {
                "query_task_id": expected_query["query_task_id"],
                "query_identity_sha256": expected_query["query_identity_sha256"],
                "method": "GET",
                "path": path,
            }
            observed_at = (
                base_time + timedelta(seconds=len(events) + 1)
            ).isoformat()
            add_event(
                "icom_public_get",
                "GET",
                path,
                [call_id],
                {
                    "source_task_id": expected_query["source_task_id"],
                    "query_task_id": expected_query["query_task_id"],
                    "call_id": call_id,
                    "call_identity_sha256": digest(call_identity),
                    "query_identity": identity,
                    "query_identity_sha256": expected_query["query_identity_sha256"],
                    "url": f"https://sfs-api.icomtours.com{path}{suffix}",
                    "path": path,
                    "query": query,
                    "travel_date": query.get("date"),
                    "captured_at": observed_at,
                    "raw_response_sha256": response_sha,
                    "normalized_evidence_sha256": digest({"normalized": call_id}),
                },
                response_sha,
            )

    binding: dict[str, object] = {
        "schema_version": _BINDING_SCHEMA_VERSION,
        "anchor_version": anchor_version,
        "authority_key_id": authority_key_id,
        "install_id": install_id,
        "composition": composition,
        "composition_sha256": composition_sha256,
        "runtime_identity": runtime_identity,
        "challenge": challenge,
        "pre_event_count": 0,
        "pre_chain_sha256": composition_sha256,
        "post_event_count": len(events),
        "post_chain_sha256": events[-1]["receipt_sha256"],
        "companion_heartbeat_receipt": events[0],
        "receipts": events,
    }
    binding["binding_digest"] = digest(binding)
    checkpoint_binding = _fixture_checkpoint_binding()
    checkpoint_sha256 = list(checkpoint_binding["ordered_checkpoint_sha256"])
    fixture_worker_receipt, fixture_model_receipt, _fixture_trace_receipt = (
        _fixture_worker_model_receipts_for_challenge(challenge)
    )
    terminal_job = {
        "checkpoint_sha256": checkpoint_sha256,
        "checkpoint_chain_sha256": digest(checkpoint_sha256),
        "result_sha256": digest({"terminal": "result"}),
        "worker_runtime_receipt_sha256": digest(fixture_worker_receipt),
        "model_execution_receipt_sha256": fixture_model_receipt[
            "receipt_sha256"
        ],
    }
    job_member_summary = _job_member_summary(
        job_graph,
        terminal_job,
        events,
        execution_capability_id="20000000-0000-4000-8000-000000000001",
        execution_attempt_digest="7" * 64,
    )
    receipt: dict[str, object] = {
        "schema_version": _RECEIPT_SCHEMA_VERSION,
        "anchor_version": anchor_version,
        "authority_key_id": authority_key_id,
        "challenge_id": challenge["challenge_id"],
        "nonce_digest": challenge["nonce_digest"],
        "binding_digest": binding["binding_digest"],
        "run_id": challenge["run_id"],
        "tested_commit_sha": commit_sha,
        "runtime_identity": runtime_identity,
        "pre_event_count": 0,
        "post_event_count": len(events),
        "delta_digest": digest(events),
        "job_member_summary": job_member_summary,
        "issued_at": challenge["issued_at"],
        "verified_at": (
            base_time + timedelta(seconds=len(events) + 1)
        ).isoformat(),
    }
    receipt["signature"] = sign(_receipt_proof_payload(receipt))
    binding["authority_receipt"] = receipt
    return binding


def _realistic_e2e_evidence(
    *, run_id: str = "fixture-formal-run"
) -> dict[str, object]:
    """A full passing layer-6 runner bundle that survives the strong compact
    contract (C-118): ``run_status`` completed, the 15-item ``done_gate`` all
    passed, and the repo / runtime / Companion identity plus the
    event-injection / timeout / runner contracts the committed layer-6 compact
    must preserve.  Values are synthetic and secret-free."""
    source = _fixture_formal_source_binding()
    evidence: dict[str, object] = {
        "schema_version": "tripchord-live-v4-done-gate-report",
        "run_status": "completed",
        "gate_run_id": run_id,
        "repo_revision": {
            "toplevel": "/repo",
            "branch": "main",
            "commit_sha": "a" * 40,
            "worktree_dirty": False,
        },
        "runtime_before_run": {
            "model_provider": "test-provider",
            "primary_model": "test-model",
            "model_enabled": True,
            "model_required": True,
            "runtime_provenance": {
                "pid": 1,
                "repo_toplevel": "/repo",
                "commit_sha": "a" * 40,
                "dependency_lock_sha256": "d" * 64,
                "live_system_source_sha256": "e" * 64,
                "python_version": "3.12.0",
                "python_executable": "/usr/bin/python3",
                "started_at": "2026-08-10T00:00:00+00:00",
            },
        },
        "formal_live_source_binding": source,
        "companion_preflight": {
            "status": "connected",
            "stale_after_seconds": 45,
            "companions": [
                {
                    "companion_id": "comp-1",
                    "providers": ["ctrip", "qunar", "tongcheng"],
                    "is_fresh": True,
                    "age_seconds": 3,
                    # C-122 HG-A: exactly the six BROWSER Companion OTA scopes.
                    "authorized_scope_keys": sorted(gate._CERTIFIED_OTA_SCOPES),
                }
            ],
        },
        "done_gate": _matching_done_gate(),
        "api_payload_candidate_set_sha256": source["challenge"][  # type: ignore[index]
            "candidate_set_sha256"
        ],
        # C-122 round-19 (gap 4): the raw request identity the compact builder
        # lifts into the layer-6 compact — the checkpoint binding's request SHA
        # is bound to this api_payload_sha256, so a foreign request-payload
        # binding fails closed.
        "request_identity": {
            "scenario_sha256": "a" * 64,
            "api_payload_sha256": _FIXTURE_REQUEST_SHA256,
            "digests_are_distinct_contracts": True,
        },
        "scenario_sha256": "a" * 64,
        "event_injection_contract": {
            "mode": "synthetic_sold_out_fault_injection",
            "source": "tripchord-done-gate-synthetic-fault",
            "platform_sold_out_observed": False,
            "platform_price_change_observed": False,
            "verified_change_scope": (
                "different_available_replacement_identity_not_platform_sold_out"
            ),
            "claim_boundary": "only_affected_component_recheck",
        },
        "timeout_contract": {
            "server_execution_timeout_seconds": 3600,
            "client_wait_timeout_seconds": 3600,
            "minimum_client_margin_seconds": 30,
        },
        "runner_contract": {
            "require_model_enhancement": True,
            "maximum_quote_age_minutes": 15,
            "minimum_recommendable_options": 2,
        },
        # C-122 supervision 01:10: the job control plane's record of the pairs
        # the run ACTUALLY sealed — the compact merges these into the
        # v4_source_graph evidence so the pair-id set is bound to an independent
        # checkpoint, not just the producer's own claim.  The fixture keeps the
        # bindings in agreement with the compact's pair_ids (all three canonical).
        # C-122 supervision 18:13 (Fix 4): the raw binding also carries the full
        # chain / dates / request / content so the compact can re-derive the
        # complete desensitized checkpoint binding.
        "context": {"pair_checkpoint_binding": _fixture_checkpoint_binding()},
    }
    source = evidence["formal_live_source_binding"]
    assert isinstance(source, dict)
    _attach_fixture_formal_context(evidence, source)
    return evidence


def test_formal_icom_query_groups_accept_concurrent_group_order_but_not_membership_drift() -> None:
    """Real worker transfer tasks may finish in any GROUP order; every group's
    identity and internal three-endpoint sequence remain exact and complete."""
    from tripchord.formal_live_source import _validate_business_event_details

    binding = _fixture_formal_source_binding()
    challenge = binding["challenge"]
    assert isinstance(challenge, dict)
    graph = challenge["job_graph"]
    assert isinstance(graph, dict)
    receipts = binding["receipts"]
    assert isinstance(receipts, list)
    non_icom = [event for event in receipts if event["kind"] != "icom_public_get"]
    grouped: dict[str, list[dict[str, object]]] = {}
    for event in receipts:
        if event["kind"] != "icom_public_get":
            continue
        details = event["details"]
        assert isinstance(details, dict)
        grouped.setdefault(str(details["query_task_id"]), []).append(event)
    reordered = [
        *non_icom,
        *(event for group in reversed(tuple(grouped.values())) for event in group),
    ]
    _validate_business_event_details(
        reordered,
        job_graph=graph,
        candidate_set_sha256=str(challenge["candidate_set_sha256"]),
        challenge_id=str(challenge["challenge_id"]),
        run_id=str(challenge["run_id"]),
        require_complete=True,
    )

    duplicated = [*reordered, *next(iter(grouped.values()))]
    with pytest.raises(ValueError, match=r"exact public GET|duplicate or foreign"):
        _validate_business_event_details(
            duplicated,
            job_graph=graph,
            candidate_set_sha256=str(challenge["candidate_set_sha256"]),
            challenge_id=str(challenge["challenge_id"]),
            run_id=str(challenge["run_id"]),
            require_complete=True,
        )


def _repo_head_or_none() -> str | None:
    """The HEAD sha of the patched repo root, or None when it is not a repo —
    the raw layer-6 fixture models the REAL flow where the runner snapshots the
    tested revision, so its compact must bind the repo that is actually
    committed (C-122 acceptance: repo == runtime == S)."""
    try:
        return gate._git("rev-parse", "HEAD", check=True).stdout.strip()
    except Exception:
        return None


def _populate_required_evidence(
    staging_dir: Path, *, run_id: str = "fixture-formal-run"
) -> None:
    """Write the fixed required raw-evidence inputs into staging so main()'s
    evidence-contract gate passes and the commit phase is actually exercised.

    The layer-5/6 raw files carry REALISTIC passing verdicts (C-118): the
    desensitized compact artifacts derived from them must survive the strong
    blob-read-back contract — the six registry-derived certified canary scopes
    (five browser Companion OTA + iCom public-API) each fresh/authorized/
    read-only/passed for layer 5, and the full fifteen done-gate checks all
    passed plus the
    repo/runtime/Companion identity for layer 6.
    """
    staging_dir.mkdir(exist_ok=True)
    (staging_dir / "product-acceptance.json").write_text(
        '{"passed": true}\n', encoding="utf-8"
    )
    (staging_dir / "browser-e2e.json").write_text('{"passed": true}\n', encoding="utf-8")
    (staging_dir / "browser-e2e-screenshot.png").write_bytes(b"PNG")
    (staging_dir / "live-canary-certified.json").write_text(
        json.dumps(_matching_canary()), encoding="utf-8"
    )
    raw_e2e = _realistic_e2e_evidence(run_id=run_id)
    head = _repo_head_or_none()
    if head is not None:
        raw_e2e["repo_revision"]["commit_sha"] = head  # type: ignore[index]
        raw_e2e["runtime_before_run"]["runtime_provenance"]["commit_sha"] = head  # type: ignore[index]
        source = _fixture_formal_source_binding(head, run_id=run_id)
        _attach_fixture_formal_context(raw_e2e, source)
    (staging_dir / "live-done-gate-v4.json").write_text(
        json.dumps(raw_e2e), encoding="utf-8"
    )


def _populate_full_required_evidence(
    monkeypatch: pytest.MonkeyPatch, staging_dir: Path
) -> None:
    """Full canonical staging for a passing publish (C-122 round-19 02:56
    supervision / gap 3): every fixed evidence input — the raw layer-5/6
    evidence, the acceptance / e2e artifacts and the screenshot — plus the
    derived layer-5/6 compact artifacts.

    The manifest contract is the FIXED full evidence set and the publish
    preflight no longer derives the expected names from whatever staging
    happens to hold, so any commit-phase test must stage the complete set
    (including the compacts) or the publish fails closed.  A persisted
    bridge-state file is simulated so the layer-6 compact's bridge-state lease
    bindings carry a valid sha256 (C-122 Fix 2); the module-level bridge
    snapshots are cleared so the compact derives from THIS test's file bytes.
    """
    bridge_state_path = staging_dir.parent / "bridge-state.json"
    bridge_state_path.write_text(
        json.dumps(
            {
                "schema_version": "tripchord-browser-bridge-state-v2",
                "saved_at": "2026-08-10T00:00:00+00:00",
                "tasks": [],
                "reload_requests": [],
            }
        ),
        encoding="utf-8",
    )
    monkeypatch.setenv(gate._BRIDGE_STATE_ENV, str(bridge_state_path))
    gate._BRIDGE_STATE_SNAPSHOT = None
    gate._BRIDGE_STATE_SNAPSHOT_AFTER = None
    _populate_required_evidence(staging_dir, run_id=_TEST_RUN_ID)
    gate._generate_compact_evidence(staging_dir)


