def _frozen_v4_fixture_pair_id(departure: str, return_date: str) -> str:
    """Build a well-formed canonical frozen-scenario ``date-pair:`` id via the
    canonical digest function, so a counter-example fixture always matches what
    the real producer seals for the frozen maldives scenario (C-122 supervision
    01:10 Block 1).  This helper is used ONLY for counter-example (foreign /
    swapped / extra) ids; the PASSING fixture pair set is NOT hardcoded here —
    it is derived from ``frozen_v4_canonical_pair_ids`` (R44).
    """
    digest = frozen_v4_pair_id_digest(
        date.fromisoformat(departure), date.fromisoformat(return_date)
    )
    return f"date-pair:{departure}:{return_date}:{digest}"


def _frozen_query_task_ids(
    pair_id: str, departure_s: str, return_s: str
) -> tuple[str, ...]:
    """Full ``query:<platform>:<kind>:<digest>`` task ids for one pair, DERIVED
    from the REAL production builder — never hand-written (C-round2 04:05Z 增量
    打回: fixtures must be generated by the real builder so a hand-written digest
    cannot mask the producer/consumer contract).

    For a canonical frozen trio pair the ids are the authoritative per-pair set
    (``frozen_v4_per_pair_query_task_ids``), the SAME set the checkpoint /
    compact / consumer bind against.  For a counter-example's foreign pair the
    ids are rebuilt through the SAME production builder (``FlexibleQueryPlanBuilder``
    + the frozen window + the frozen stay-plan candidate set) with that pair's
    own dates, so a doctored / swapped set is still a genuinely-built,
    self-consistent contract the validator must reject by the per-pair exact
    authority."""
    from tripchord.planning.flexible_dates import (
        LIVE_V5_PLATFORMS,
        AuditableDatePair,
        DateExplorationMode,
        DateExplorationResult,
        DatePairSource,
        DateSearchMetrics,
        DateSearchMetricStatus,
        FlexibleQueryPlanBuilder,
        PlatformRatePolicy,
        QueryPlanPolicy,
    )

    for per_pair in frozen_v4_ordered_per_pair_query_task_ids():
        if pair_id in per_pair:
            return tuple(per_pair[pair_id])
    candidate_set = _frozen_candidate_set()
    window = _FROZEN_V4_TRAVEL_WINDOW
    builder = FlexibleQueryPlanBuilder(platforms=LIVE_V5_PLATFORMS)
    departure = date.fromisoformat(departure_s)
    return_d = date.fromisoformat(return_s)
    pair = AuditableDatePair(
        id=pair_id,
        rank=1,
        departure_date=departure,
        return_date=return_d,
        night_count=(return_d - departure).days,
        source=DatePairSource.FUSED_FARE_HINT,
        audit_reason="counter-example foreign pair query-task authority",
    )
    exploration = DateExplorationResult(
        mode=DateExplorationMode.FULL_CALENDAR_TOP_K,
        sampled_not_exhaustive=False,
        universe_size=window.universe_size,
        candidates=(pair,),
        search_metrics=DateSearchMetrics(
            universe_size=window.universe_size,
            coarse_window_pair_count=1,
            prior_observed_pair_count=0,
            prior_coverage=Decimal(0),
            shortlist_pair_count=1,
            shortlist_coverage=Decimal(1),
            metric_status=DateSearchMetricStatus.FULL_WINDOW_EVALUABLE,
            evaluation_note="counter-example foreign pair query-task authority",
        ),
    )
    policy = QueryPlanPolicy(
        max_exact_pairs=1,
        platform_rates=tuple(
            PlatformRatePolicy(platform=platform) for platform in LIVE_V5_PLATFORMS
        ),
    )
    plan = builder.build(
        window,
        exploration,
        policy,
        stay_plan_candidate_set=candidate_set,
    )
    return tuple(sorted(task.id for task in plan.tasks))


# The passing fixture's pair-id set: the CANONICAL frozen ordered trio, DERIVED
# (not hardcoded — C-122 R44 forbids a hand-written fixture trio as production
# truth) from the same committed inputs producer / compact / consumer share
# (frozen window + committed reference_date + selection algorithm), so the
# fixture always matches the exact ordered trio a real frozen run seals.
_FIXTURE_PAIR_IDS = frozen_v4_canonical_pair_ids()

# The shared fixture request identity every checkpoint binding must carry (the
# run's request SHA — C-122 supervision 18:13 wrong-request counter-example).
_FIXTURE_REQUEST_SHA256 = "f" * 64
# The per-pair dates mirror ``_FIXTURE_PAIR_IDS`` (in the same order), so each
# binding's dates agree with its pair id's own embedded dates.
_FIXTURE_PAIR_DATES = tuple(
    (pair_id.split(":")[1], pair_id.split(":")[2]) for pair_id in _FIXTURE_PAIR_IDS
)


def _checkpoint_binding_for_pair_ids(
    pair_ids: tuple[str, ...],
    pair_dates: tuple[tuple[str, str], ...],
    request_sha256: str = _FIXTURE_REQUEST_SHA256,
) -> dict[str, object]:
    """A self-consistent desensitized checkpoint binding for an arbitrary ordered
    pair-id set: one binding per pair, each carrying the checkpoint model's
    authoritative recomputable ``checkpoint_sha256`` over its OWN carried fields,
    an ordered digest chain with a recomputable chain digest, and ONE request
    identity shared by every binding (C-122 supervision 18:13 Fix 4).
    C-122 round-19 (gap 4): each binding is a ``completed`` checkpoint whose
    per-group query-task set is EXACTLY the canonical frozen graph's browser
    Source-id set, and whose ``run_summary_sha256`` recomputes from the carried
    business-summary fields via the checkpoint model's authoritative ``_run_summary``
    digest.  The validator recomputes every digest from these carried fields, so
    the fixture must be genuinely self-consistent — a copied / doctored digest
    fails the same-raw counter-example.  Parameterizing the pair set lets an R44
    counter-example rebuild a FULLY self-consistent chain for a foreign trio
    (joint replacement + recomputed chain)."""
    from tripchord.agents.live_jobs import LivePlanningPairCheckpoint

    bindings: list[dict[str, object]] = []
    for index, pair_id in enumerate(pair_ids):
        departure_s, return_s = pair_dates[index]
        # R44 后续 (blocker C): the REAL producer / checkpoint seals FULL
        # query-task ids — ``query:<platform>:<kind>:<digest>`` (the
        # ``FlexibleQueryTask.id`` namespace, ``query:ctrip:flight:…``) — whose
        # OWNERSHIP part is ``<platform>:<kind>`` (``ctrip:flight``).  The
        # fixture must mirror the real production contract so it cannot mask a
        # validator that forces ``source-*`` ids or bare ownership ids.
        query_task_ids = list(
            _frozen_query_task_ids(pair_id, departure_s, return_s)
        )
        captured_at = "2026-08-10T00:00:00+00:00"
        # C-122 round-19 (gap 4): the full business-summary fields for a
        # COMPLETED checkpoint — run_purpose / finalization / decision typed, a
        # source-task count equal to the frozen per-pair query count, both
        # completion flags true, and NO failure class.
        run_summary_fields = {
            "state": "completed",
            "run_purpose": "exploration_and_publication",
            "finalization_state": "finalized",
            "decision_state": "recommended",
            "source_task_count": len(query_task_ids),
            "exploration_seal_passed": True,
            "all_platforms_complete": True,
            "failure_class": None,
        }
        run_summary_sha256 = LivePlanningPairCheckpoint._digest(
            LivePlanningPairCheckpoint._run_summary(run_summary_fields)
        )
        summary = LivePlanningPairCheckpoint._checkpoint_summary(
            {
                "schema_version": "live-pair-checkpoint-v1",
                "request_sha256": request_sha256,
                "sequence": index + 1,
                "date_pair_id": pair_id,
                "departure_date": departure_s,
                "return_date": return_s,
                "state": "completed",
                "query_task_ids": query_task_ids,
                "run_summary_sha256": run_summary_sha256,
                "captured_at": captured_at,
            }
        )
        checkpoint_sha256 = LivePlanningPairCheckpoint._digest(summary)
        bindings.append(
            {
                "sequence": index + 1,
                "date_pair_id": pair_id,
                "departure_date": departure_s,
                "return_date": return_s,
                "state": "completed",
                "query_task_ids": query_task_ids,
                "query_task_ids_sha256": gate._canonical_sha256(query_task_ids),
                "run_purpose": run_summary_fields["run_purpose"],
                "finalization_state": run_summary_fields["finalization_state"],
                "decision_state": run_summary_fields["decision_state"],
                "source_task_count": run_summary_fields["source_task_count"],
                "exploration_seal_passed": run_summary_fields["exploration_seal_passed"],
                "all_platforms_complete": run_summary_fields["all_platforms_complete"],
                "failure_class": run_summary_fields["failure_class"],
                "run_summary_sha256": run_summary_sha256,
                "captured_at": captured_at,
                "checkpoint_sha256": checkpoint_sha256,
                "request_sha256": request_sha256,
            }
        )
    ordered = [str(b["checkpoint_sha256"]) for b in bindings]
    return {
        "passed": True,
        "count": len(bindings),
        "ordered_checkpoint_sha256": ordered,
        "checkpoint_chain_sha256": gate._canonical_sha256(ordered),
        "request_sha256": request_sha256,
        "bindings": bindings,
    }


def _fixture_checkpoint_binding() -> dict[str, object]:
    """A self-consistent desensitized checkpoint binding for the passing
    fixture (see ``_checkpoint_binding_for_pair_ids`` for the full contract)."""
    return _checkpoint_binding_for_pair_ids(_FIXTURE_PAIR_IDS, _FIXTURE_PAIR_DATES)


