def _layer6_compact_fixture() -> dict[str, object]:
    """A layer-6 compact that satisfies the strong C-118/C-122 blob contract:
    the fifteen done-gate checks all passed, each carrying its structured
    per-item evidence, plus the repo / runtime / Companion identity, the
    candidate-set / scenario SHA bindings and the event-injection / timeout /
    runner contracts."""
    done_gate = _matching_done_gate()
    done_gate["check_count"] = 15  # type: ignore[index]
    done_gate["passed_check_count"] = 15  # type: ignore[index]
    source = _fixture_formal_source_binding()
    from tripchord.formal_live_source import formal_source_evidence_summary

    formal_summary = formal_source_evidence_summary(
        source,
        source["authority_receipt"],
        source["challenge"],
        expected_context={
            key: source["challenge"][key]  # type: ignore[index]
            for key in (
                "run_id",
                "tested_commit_sha",
                "runtime_identity",
                "request_sha256",
                "candidate_set_sha256",
                "scenario_sha256",
                "job_graph",
            )
        },
    )
    worker_receipt, model_receipt, _trace_receipt = (
        _fixture_worker_model_receipts(source)
    )
    runtime_provenance = worker_receipt["runtime_provenance"]
    worker_identity = worker_receipt["worker_runtime_identity"]
    assert isinstance(runtime_provenance, dict)
    assert isinstance(worker_identity, dict)
    worker_summary_unsigned: dict[str, object] = {
        "schema_version": "tripchord-live-worker-runtime-summary-v1",
        "runtime_receipt_sha256": gate._canonical_sha256(worker_receipt),
        "runtime": worker_receipt["runtime"],
        "providers": worker_receipt["providers"],
        "spec_sha256": worker_receipt["spec_sha256"],
        "api_runtime_identity_sha256": worker_receipt[
            "api_runtime_identity_sha256"
        ],
        "runtime_provenance": {
            key: runtime_provenance[key]
            for key in (
                "commit_sha",
                "dependency_lock_sha256",
                "live_system_source_sha256",
            )
        },
        "worker_runtime_identity": {
            key: worker_identity[key]
            for key in (
                "commit_sha",
                "dependency_lock_sha256",
                "live_system_source_sha256",
                "python_version",
                "started_at",
                "pid",
            )
        },
        "worker_runtime_identity_sha256": model_receipt[
            "worker_runtime_identity_sha256"
        ],
        "model_agents_required": True,
        "model_runtime_identity": worker_receipt["model_runtime_identity"],
    }
    worker_summary = {
        **worker_summary_unsigned,
        "summary_sha256": gate._canonical_sha256(worker_summary_unsigned),
    }
    source_receipts = [
        event["details"]["source_execution_receipt"]  # type: ignore[index]
        for event in source["receipts"]  # type: ignore[union-attr]
        if event["kind"] == "browser_complete"  # type: ignore[index]
    ]
    ordered_source_hashes = [
        receipt["receipt_sha256"] for receipt in source_receipts
    ]
    source_receipt_set = {
        "schema_version": "tripchord-source-execution-receipt-set-v1",
        "count": len(source_receipts),
        "ordered_receipt_sha256": ordered_source_hashes,
        "receipt_chain_sha256": gate._canonical_sha256(
            ordered_source_hashes
        ),
        "receipts": source_receipts,
    }
    heartbeat = source["companion_heartbeat_receipt"]
    assert isinstance(heartbeat, dict)
    heartbeat_details = heartbeat["details"]
    assert isinstance(heartbeat_details, dict)
    heartbeat_value = heartbeat_details["heartbeat"]
    assert isinstance(heartbeat_value, dict)
    compact: dict[str, object] = {
        "schema_version": gate._LAYER6_COMPACT_SCHEMA,
        "run_status": "completed",
        "done_gate": done_gate,
        "repo_revision": {
            "branch": "main",
            "commit_sha": "a" * 40,
            "worktree_dirty": False,
        },
        "runtime_before_run": {
            "model_provider": "test-provider",
            "primary_model": "test-model",
            "worker_model_runtime": {
                "enabled": True,
                "required": True,
                **worker_receipt["model_runtime_identity"],  # type: ignore[misc]
                "runtime_bundle_spec_sha256": worker_receipt["spec_sha256"],
            },
            "runtime_provenance": {
                "commit_sha": "a" * 40,
            },
        },
        "formal_live_source_summary": formal_summary,
        "worker_runtime_summary": worker_summary,
        "model_execution_receipt": model_receipt,
        "source_execution_receipts": source_receipt_set,
        "runtime_identity_sha256": formal_summary["runtime_identity_sha256"],
        "gate_run_id": source["challenge"]["run_id"],  # type: ignore[index]
        "companion_preflight": {
            "status": "connected",
            "stale_after_seconds": 45,
            "companions": [
                {
                    "companion_id": "comp-1",
                    # C-122 round-19: exactly the CERTIFIED BROWSER Companion OTA
                    # scopes (five scopes, registry-derived); ``icom:transfer`` is
                    # a public-API scope and never appears in a Companion's
                    # authorization set, and the DISABLED ``tongcheng:lodging``
                    # never enters the compact.
                    "authorized_scope_keys": sorted(gate._CERTIFIED_OTA_SCOPES),
                    "build_identity": heartbeat_value["build_identity"],
                    "runtime_instance_id": heartbeat_value[
                        "runtime_instance_id"
                    ],
                }
            ],
        },
        "api_payload_candidate_set_sha256": source["challenge"][  # type: ignore[index]
            "candidate_set_sha256"
        ],
        # C-122 round-19 (gap 4): the raw request payload SHA the checkpoint
        # binding's request identity must bind to (matches the fixture's
        # checkpoint request_sha256).
        "api_payload_sha256": _FIXTURE_REQUEST_SHA256,
        "scenario_sha256": "a" * 64,
        "event_injection_contract": {
            "mode": "synthetic_sold_out_fault_injection",
            "source": "tripchord-done-gate-synthetic-fault",
        },
        "timeout_contract": {"server_execution_timeout_seconds": 3600},
        "runner_contract": {"require_model_enhancement": True},
        "bridge_state_lease_preflight": {
            # A repo-relative identifier whose file does not exist in the real
            # repo tree, so the contract's live-recompute check is skipped for
            # the fixture (dedicated tests exercise recompute with their own
            # file under a monkeypatched ROOT).
            "file": ".runtime/done-gate-test-fixture-bridge-state.json",
            "sha256": "a" * 64,
            "residual": [],
        },
        # C-122 round-18 item 6: the POST-run lease binding is contract-required
        # too — the run must leave no residual queued/claimed/reload behind.
        "bridge_state_lease_postcheck": {
            "file": ".runtime/done-gate-test-fixture-bridge-state.json",
            "sha256": "a" * 64,
            "residual": [],
        },
        # R44 后续 (blocker A): the compact's raw_evidence binds to its FIXED raw
        # origin — file name, tracked path, committed=false, 64-hex sha256 and
        # positive size_bytes — matching the layer-6 producer's emission.
        "raw_evidence": {
            "file": gate._COMPACT_RAW_EVIDENCE_MAPPING[gate._COMPACT_E2E_STAGED_NAME],
            "path": gate._COMPACT_RAW_EVIDENCE_TRACKED[gate._COMPACT_E2E_STAGED_NAME],
            "committed": False,
            "sha256": "a" * 64,
            "size_bytes": 5678,
        },
    }
    return compact


