def test_c4_complete_self_consistent_binding_requires_production_capability(
    staging_dir: Path,
) -> None:
    """A complete, correctly hashed and MACed hand forge fails all consumers.

    This is the faithful bypass from independent comment
    3d5717e4-913b-446a-ae7a-f92008bca8ea: the attacker supplies every field,
    exact event order/path/status and recomputes every public digest plus an
    internally consistent signature using its own key.  It still lacks the
    fixed production verification anchor loaded by the API installation.
    """

    from tripchord.formal_live_source import validate_formal_source_binding

    forged = _fixture_formal_source_binding(
        "a" * 40,
        install_id="99999999-9999-4999-8999-999999999999",
        authority_secret="foreign-manual-authority-secret-000000000000000000000000",
        trust=False,
    )

    with pytest.raises(ValueError, match="foreign verification anchor"):
        validate_formal_source_binding(forged)
    raw_payload = _realistic_e2e_evidence()
    raw_payload["formal_live_source_binding"] = copy.deepcopy(forged)
    raw_payload["formal_live_source_authority_receipt"] = copy.deepcopy(
        forged["authority_receipt"]
    )
    raw_payload["formal_live_source_challenge"] = copy.deepcopy(
        forged["challenge"]
    )
    staging_dir.mkdir()
    forged_raw = staging_dir / "live-done-gate-v4.json"
    forged_raw.write_text(json.dumps(raw_payload), encoding="utf-8")
    forged_raw.chmod(0o600)
    with pytest.raises(
        gate.GateStateChangedError,
        match="formal production source binding",
    ):
        gate._compact_live_e2e(staging_dir)


def test_c4_complete_binding_cannot_be_retrusted_with_bridge_token() -> None:
    """The public Browser credential must never mint source authority.

    This preserves every required field, event, path, subject, chain digest and
    MAC while re-signing the complete binding with the same bridge token that
    the gate currently possesses.  The binding is still hand-authored outside
    the production ``_install_browser_bridge`` authority and must fail closed.
    """

    from tripchord.formal_live_source import validate_formal_source_binding

    bridge_token = gate._bridge_token() or ("B" * 64)
    forged = _fixture_formal_source_binding(
        install_id="88888888-8888-4888-8888-888888888888",
        authority_secret=bridge_token,
        trust=False,
    )

    with pytest.raises(ValueError, match="foreign verification anchor"):
        validate_formal_source_binding(forged)


def test_formal_source_public_constructor_cannot_self_register_trust() -> None:
    """13:47Z faithful red: ordinary code cannot mint a trusted authority.

    The rejected implementation exposed a zero-capability constructor which
    generated a key and immediately inserted it into a mutable process-global
    registry.  Merely constructing the object therefore made its future
    hand-authored receipts trusted in that process.
    """

    from tripchord.formal_live_source import FormalLiveSourceAuthority

    with pytest.raises(TypeError, match="formal API startup"):
        FormalLiveSourceAuthority(commit_sha="a" * 40)


def test_formal_source_signing_is_not_a_business_principal_route() -> None:
    """13:47Z faithful red: normal API principals cannot bind or validate."""

    import tripchord.main as api_main

    paths = {getattr(route, "path", None) for route in api_main.app.routes}
    assert "/api/v1/agents/runtime" in paths
    assert "/api/v1/agents/runtime/formal-live-source/bind" not in paths
    assert "/api/v1/agents/runtime/formal-live-source/validate" not in paths


def _fresh_installed_formal_authority(
    tmp_path: Path,
    *,
    ledger_name: str = "ledger.json",
    now: Any = None,
) -> tuple[Any, dict[str, object]]:
    import httpx
    import tripchord.main as api_main
    from fastapi import FastAPI
    from tripchord.formal_live_source import formal_job_graph_for_frozen_v4
    from tripchord.planning.stay_plans import system_stay_plan_candidate_set

    assert _TEST_FORMAL_PRIVATE_KEY_PATH is not None
    target = FastAPI()
    configured = api_main.settings.model_copy(
        update={
            "browser_bridge_enabled": True,
            "browser_bridge_token": "isolated-formal-test-bridge-token-" + "B" * 32,
            "browser_bridge_control_token": None,
            "browser_companion_auto_reload_enabled": False,
            "model_agents_required": False,
            "adaptive_agent_scaling_enabled": False,
        }
    )
    client = httpx.AsyncClient(transport=httpx.MockTransport(lambda _request: None))
    api_main._install_browser_bridge(
        target,
        configured,
        icom_http_client=client,
        now=now or (lambda: NOW),
        sleep=_c4_noop_sleep,
        formal_source_private_key_path=_TEST_FORMAL_PRIVATE_KEY_PATH,
        formal_source_ledger_path=tmp_path / ledger_name,
    )
    authority = target.state.formal_live_source_authority
    runtime = api_main.PROVENANCE.to_dict()
    context = {
        "run_id": "isolated-formal-run",
        "tested_commit_sha": runtime["commit_sha"],
        "runtime_identity": runtime,
        "request_sha256": "1" * 64,
        "candidate_set_sha256": (
            system_stay_plan_candidate_set().candidate_set_sha256
        ),
        "scenario_sha256": "3" * 64,
        "job_graph": formal_job_graph_for_frozen_v4(
            terminal_job_id="live-job-isolated-formal",
            request_sha256="1" * 64,
            adults=2,
        ),
    }
    return authority, context


def test_formal_offline_validation_uses_explicit_api_certified_root(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """C-146: a foreign shell root cannot replace the API-selected anchor."""

    from tripchord.formal_live_source import (
        provision_formal_source_trust_root,
        validate_formal_execution_capability,
        validate_formal_source_challenge,
    )

    assert _TEST_FORMAL_CONTROL_TOKEN_PATH is not None
    authority, context = _fresh_installed_formal_authority(tmp_path)
    issued = authority.issue_challenge(context)
    foreign_root = tmp_path / "foreign-shell-root"
    provision_formal_source_trust_root(foreign_root)
    monkeypatch.setenv("TRIPCHORD_FORMAL_SOURCE_TRUST_ROOT", str(foreign_root))

    with pytest.raises(ValueError, match="foreign verification anchor"):
        validate_formal_source_challenge(issued["challenge"])

    certified_root = _TEST_FORMAL_CONTROL_TOKEN_PATH.parent
    checked = validate_formal_source_challenge(
        issued["challenge"],
        trust_root=certified_root,
    )
    assert checked["challenge_id"] == issued["challenge"]["challenge_id"]
    validate_formal_execution_capability(
        issued["execution_capability"],
        issued["challenge"],
        trust_root=certified_root,
    )


def _formal_companion_binding(
    *,
    companion_id: str = "formal-heartbeat-companion",
    runtime_instance_id: str = "formal-heartbeat-runtime-v1",
    manifest_version: str = "formal-heartbeat-build-v1",
    build_sha256: str = "9" * 64,
    adapter_version: str = "0.2.0",
) -> dict[str, object]:
    identity: dict[str, object] = {
        "companion_id": companion_id,
        "providers": ["ctrip", "qunar", "tongcheng"],
        "authorized_scope_keys": sorted(gate._CERTIFIED_OTA_SCOPES),
        "adapter_version": adapter_version,
        "contract_version": "tripchord-capability-v1",
        "runtime_instance_id": runtime_instance_id,
        "build_identity": {
            "protocol_version": "tripchord-companion-control-v1",
            "manifest_version": manifest_version,
            "build_sha256": build_sha256,
            "content_runtime_version": runtime_instance_id,
        },
    }
    identity["identity_sha256"] = hashlib.sha256(
        json.dumps(
            identity,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return identity


def test_formal_challenge_single_active_is_atomic_across_restart(tmp_path: Path) -> None:
    authority, context = _fresh_installed_formal_authority(tmp_path)
    issued = authority.issue_challenge(context)
    ledger = tmp_path / "ledger.json"
    before = ledger.read_bytes()
    snapshot = authority.snapshot()

    with pytest.raises(ValueError, match="active challenge"):
        authority.issue_challenge({**context, "run_id": "second-formal-run"})
    assert ledger.read_bytes() == before
    assert authority.snapshot() == snapshot
    assert authority.public_status()["challenge_active"] is True

    restarted, _ = _fresh_installed_formal_authority(tmp_path)
    with pytest.raises(ValueError, match="active challenge"):
        restarted.issue_challenge({**context, "run_id": "restart-foreign-run"})
    assert ledger.read_bytes() == before
    assert issued["challenge"]["run_id"] == context["run_id"]


def test_formal_issue_retry_returns_same_signed_capability_and_challenge(
    tmp_path: Path,
) -> None:
    """RETURN-8db00bb: a committed issue response is durably retrievable."""

    authority, context = _fresh_installed_formal_authority(tmp_path)
    first = authority.issue_challenge(
        context,
        idempotency_key="formal-issue-retry-1",
    )
    replay = authority.issue_challenge(
        context,
        idempotency_key="formal-issue-retry-1",
    )
    assert replay == first
    capability = first["execution_capability"]
    assert isinstance(capability, dict)
    assert capability["challenge_id"] == first["challenge"]["challenge_id"]
    assert capability["terminal_job_id"] == context["job_graph"]["terminal_job_id"]
    binding = _formal_companion_binding(companion_id="real-heartbeat-companion")
    authority.begin_activation(
        job_id=capability["terminal_job_id"],
        capability=capability,
        idempotency_key="formal-activate-retry-1",
        companion_binding=binding,
    )
    request_details = {
        key: value for key, value in binding.items() if key != "identity_sha256"
    }
    authority.record_activation_heartbeat(
        acknowledgment={
            "job_id": capability["terminal_job_id"],
            "challenge_id": capability["challenge_id"],
            "execution_capability": capability,
            "companion_binding": binding,
        },
        request_details=request_details,
        heartbeat={
            **request_details,
            "last_seen": NOW.isoformat(),
            "age_seconds": 0.0,
            "is_fresh": True,
        },
    )
    activation = {"job": {"id": capability["terminal_job_id"], "state": "queued"}}
    authority.prepare_activation_result(
        job_id=capability["terminal_job_id"],
        capability=capability,
        idempotency_key="formal-activate-retry-1",
        result=activation,
    )
    authority.mark_activation_started(
        job_id=capability["terminal_job_id"],
        capability=capability,
        idempotency_key="formal-activate-retry-1",
        result=activation,
    )
    assert authority.store_activation_result(
        job_id=capability["terminal_job_id"],
        capability=capability,
        idempotency_key="formal-activate-retry-1",
        result=activation,
    ) == activation

    restarted, _ = _fresh_installed_formal_authority(tmp_path)
    assert (
        restarted.issue_challenge(
            context,
            idempotency_key="formal-issue-retry-1",
        )
        == first
    )
    assert restarted.activation_replay(
        job_id=capability["terminal_job_id"],
        capability=capability,
        idempotency_key="formal-activate-retry-1",
        companion_binding=binding,
    ) == activation
    with pytest.raises(ValueError, match="different request"):
        restarted.activation_replay(
            job_id=capability["terminal_job_id"],
            capability=capability,
            idempotency_key="foreign-activate-retry",
            companion_binding=binding,
        )
    with pytest.raises(ValueError, match="different request"):
        restarted.issue_challenge(
            {**context, "scenario_sha256": "4" * 64},
            idempotency_key="formal-issue-retry-1",
        )


def test_formal_activation_result_rejects_orphan_without_begin_and_heartbeat(
    tmp_path: Path,
) -> None:
    """3d7dd448: a result cannot create an unbound activation ledger record."""

    authority, context = _fresh_installed_formal_authority(tmp_path)
    issued = authority.issue_challenge(
        context,
        idempotency_key="orphan-activation-issue-v1",
    )
    capability = issued["execution_capability"]
    with pytest.raises(ValueError, match=r"begin|heartbeat"):
        authority.store_activation_result(
            job_id=capability["terminal_job_id"],
            capability=capability,
            idempotency_key="orphan-activation-result-v1",
            result={"job": {"id": capability["terminal_job_id"], "state": "queued"}},
        )


@pytest.mark.asyncio
async def test_formal_activation_heartbeat_requires_real_companion_ack_path(
    tmp_path: Path,
) -> None:
    """92a0db1a: cached status cannot be promoted into a formal heartbeat."""

    import httpx
    from tripchord.providers.browser_bridge import (
        BRIDGE_TOKEN_HEADER,
        BrowserTaskBridge,
        create_browser_bridge_app,
    )

    authority, context = _fresh_installed_formal_authority(tmp_path)
    issued = authority.issue_challenge(
        context,
        idempotency_key="real-heartbeat-issue-v1",
    )
    capability = issued["execution_capability"]
    job_id = capability["terminal_job_id"]
    binding = _formal_companion_binding(companion_id="real-heartbeat-companion")
    authority.begin_activation(
        job_id=job_id,
        capability=capability,
        idempotency_key="real-heartbeat-activate-v1",
        companion_binding=binding,
    )
    bridge = BrowserTaskBridge(source_authority=authority, now=lambda: NOW)
    app = create_browser_bridge_app(
        bridge,
        bridge_token="real-heartbeat-bridge-token-000000000000",
        source_authority=authority,
    )
    common = {
        "companion_id": "real-heartbeat-companion",
        "providers": ["ctrip", "qunar", "tongcheng"],
        "authorized_scope_keys": sorted(gate._CERTIFIED_OTA_SCOPES),
        "adapter_version": "0.2.0",
        "contract_version": "tripchord-capability-v1",
        "runtime_instance_id": "formal-heartbeat-runtime-v1",
        "build_identity": binding["build_identity"],
    }
    headers = {
        BRIDGE_TOKEN_HEADER: "real-heartbeat-bridge-token-000000000000"
    }
    async with httpx.AsyncClient(
        transport=httpx.ASGITransport(app=app, client=("127.0.0.1", 51342)),
        base_url="http://tripchord.test",
    ) as client:
        prime = await client.post(
            "/v1/tasks/claim",
            headers=headers,
            json={
                **common,
                "limit": 1,
                "build_identity": binding["build_identity"],
            },
        )
        assert prime.status_code == 200

        # A genuine ordinary heartbeat remains successful, but cannot enter the
        # formal ledger without explicitly echoing the signed activation request.
        ordinary = await client.post(
            "/v1/companions/heartbeat",
            headers=headers,
            json=common,
        )
        assert ordinary.status_code == 200
        pending = ordinary.json()["formal_activation_request"]
        assert pending == {
            "job_id": job_id,
            "challenge_id": capability["challenge_id"],
            "execution_capability": capability,
            "companion_binding": binding,
        }
        assert authority.snapshot()["event_count"] == 0

        missing = await client.post(
            "/v1/companions/heartbeat",
            headers=headers,
            json={**common, "formal_activation_ack": {"job_id": job_id}},
        )
        assert missing.status_code == 422
        assert authority.snapshot()["event_count"] == 0

        foreign = await client.post(
            "/v1/companions/heartbeat",
            headers=headers,
            json={
                **common,
                "formal_activation_ack": {
                    **pending,
                    "job_id": "live-job-foreign",
                },
            },
        )
        assert foreign.status_code == 409
        assert authority.snapshot()["event_count"] == 0

        stale_build = dict(common["build_identity"])
        stale_build["build_sha256"] = "7" * 64
        stale = await client.post(
            "/v1/companions/heartbeat",
            headers=headers,
            json={
                **common,
                "build_identity": stale_build,
                "formal_activation_ack": pending,
            },
        )
        assert stale.status_code == 409
        status_snapshot = await bridge.companion_status()
        assert status_snapshot.companions[0].build_identity is not None
        assert status_snapshot.companions[0].build_identity.model_dump(
            mode="json"
        ) == common["build_identity"]
        assert authority.snapshot()["event_count"] == 0

        replaced_digest = copy.deepcopy(pending)
        replaced_digest["companion_binding"]["identity_sha256"] = "6" * 64
        digest_swap = await client.post(
            "/v1/companions/heartbeat",
            headers=headers,
            json={**common, "formal_activation_ack": replaced_digest},
        )
        assert digest_swap.status_code == 409
        assert authority.snapshot()["event_count"] == 0

        accepted = await client.post(
            "/v1/companions/heartbeat",
            headers=headers,
            json={**common, "formal_activation_ack": pending},
        )
        assert accepted.status_code == 200, accepted.text
        assert accepted.json()["formal_activation_request"] is None
    snapshot = authority.snapshot()
    assert snapshot["event_count"] == 1
    assert snapshot["events"][0]["kind"] == "browser_heartbeat"


@pytest.mark.asyncio
async def test_formal_activation_heartbeat_binds_exact_preflight_companion(
    tmp_path: Path,
) -> None:
    """3d7dd448: only the selected Companion identity may acknowledge activation."""

    import httpx
    from tripchord.providers.browser_bridge import (
        BRIDGE_TOKEN_HEADER,
        BrowserTaskBridge,
        create_browser_bridge_app,
    )

    authority, context = _fresh_installed_formal_authority(tmp_path)
    issued = authority.issue_challenge(
        context,
        idempotency_key="bound-heartbeat-issue-v1",
    )
    capability = issued["execution_capability"]
    job_id = capability["terminal_job_id"]
    binding = _formal_companion_binding()
    authority.begin_activation(
        job_id=job_id,
        capability=capability,
        idempotency_key="bound-heartbeat-activate-v1",
        companion_binding=binding,
    )
    bridge = BrowserTaskBridge(source_authority=authority, now=lambda: NOW)
    app = create_browser_bridge_app(
        bridge,
        bridge_token="bound-heartbeat-bridge-token-0000000000",
        source_authority=authority,
    )
    common = {key: value for key, value in binding.items() if key != "identity_sha256"}
    headers = {
        BRIDGE_TOKEN_HEADER: "bound-heartbeat-bridge-token-0000000000"
    }
    async with httpx.AsyncClient(
        transport=httpx.ASGITransport(app=app, client=("127.0.0.1", 51343)),
        base_url="http://tripchord.test",
    ) as client:
        ordinary = await client.post(
            "/v1/companions/heartbeat",
            headers=headers,
            json=common,
        )
        assert ordinary.status_code == 200
        pending = ordinary.json()["formal_activation_request"]
        assert pending["companion_binding"] == binding
        assert authority.snapshot()["event_count"] == 0

        foreign = await client.post(
            "/v1/companions/heartbeat",
            headers=headers,
            json={
                **common,
                "runtime_instance_id": "foreign-runtime",
                "formal_activation_ack": pending,
            },
        )
        assert foreign.status_code == 409
        assert authority.snapshot()["event_count"] == 0

        accepted = await client.post(
            "/v1/companions/heartbeat",
            headers=headers,
            json={**common, "formal_activation_ack": pending},
        )
        assert accepted.status_code == 200, accepted.text
    snapshot = authority.snapshot()
    assert snapshot["event_count"] == 1
    assert snapshot["events"][0]["details"]["companion_identity_sha256"] == binding[
        "identity_sha256"
    ]


def test_formal_activation_two_phase_state_is_durable_and_idempotent(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    """92a0db1a: every activation phase survives response loss exactly once."""

    authority, context = _fresh_installed_formal_authority(tmp_path)
    issued = authority.issue_challenge(
        context,
        idempotency_key="two-phase-issue-v1",
    )
    capability = issued["execution_capability"]
    job_id = capability["terminal_job_id"]
    binding = _formal_companion_binding(
        companion_id="two-phase-companion",
        runtime_instance_id="two-phase-runtime-v1",
        manifest_version="two-phase-build-v1",
        build_sha256="8" * 64,
        adapter_version="0.2.0",
    )
    prepared = authority.begin_activation(
        job_id=job_id,
        capability=capability,
        idempotency_key="two-phase-activate-v1",
        companion_binding=binding,
    )
    assert prepared["phase"] == "awaiting_heartbeat"

    restarted, _ = _fresh_installed_formal_authority(tmp_path)
    assert restarted.begin_activation(
        job_id=job_id,
        capability=capability,
        idempotency_key="two-phase-activate-v1",
        companion_binding=binding,
    ) == prepared
    with pytest.raises(ValueError, match="different request"):
        restarted.begin_activation(
            job_id=job_id,
            capability=capability,
            idempotency_key="two-phase-activate-v1",
            companion_binding=_formal_companion_binding(
                companion_id="two-phase-foreign-companion",
                runtime_instance_id="two-phase-runtime-v1",
                manifest_version="two-phase-build-v1",
                build_sha256="8" * 64,
                adapter_version="0.2.0",
            ),
        )

    heartbeat_request = {
        "companion_id": "two-phase-companion",
        "providers": ["ctrip", "qunar", "tongcheng"],
        "authorized_scope_keys": sorted(gate._CERTIFIED_OTA_SCOPES),
        "adapter_version": "0.2.0",
        "contract_version": "tripchord-capability-v1",
        "runtime_instance_id": "two-phase-runtime-v1",
        "build_identity": binding["build_identity"],
    }
    restarted.record_activation_heartbeat(
        acknowledgment={
            "job_id": job_id,
            "challenge_id": capability["challenge_id"],
            "execution_capability": capability,
            "companion_binding": binding,
        },
        request_details=heartbeat_request,
        heartbeat={
            **heartbeat_request,
            "last_seen": NOW.isoformat(),
            "age_seconds": 0.0,
            "is_fresh": True,
            "build_identity": binding["build_identity"],
        },
    )

    original_write = restarted._write_ledger
    started_result = {
        "job": {
            "id": job_id,
            "state": "queued",
            "attempt": 1,
            "queued_at": NOW.isoformat(),
        },
        "activation_receipt": {"capability_id": capability["capability_id"]},
    }
    restarted.prepare_activation_result(
        job_id=job_id,
        capability=capability,
        idempotency_key="two-phase-activate-v1",
        result=started_result,
    )

    def fail_write(_ledger: object) -> None:
        raise OSError("injected activation phase write failure")

    monkeypatch.setattr(restarted, "_write_ledger", fail_write)
    with pytest.raises(OSError, match="activation phase"):
        restarted.mark_activation_started(
            job_id=job_id,
            capability=capability,
            idempotency_key="two-phase-activate-v1",
            result=started_result,
        )
    monkeypatch.setattr(restarted, "_write_ledger", original_write)
    after_failure = restarted.activation_state(
        job_id=job_id,
        capability=capability,
        idempotency_key="two-phase-activate-v1",
    )
    assert after_failure["phase"] == "activation_ready"
    restarted.mark_activation_started(
        job_id=job_id,
        capability=capability,
        idempotency_key="two-phase-activate-v1",
        result=started_result,
    )
    durable_started = restarted.activation_state(
        job_id=job_id,
        capability=capability,
        idempotency_key="two-phase-activate-v1",
    )
    assert durable_started["phase"] == "started"
    assert durable_started["started_result"] == started_result
    assert durable_started["result"] == started_result
    mismatched_first_result = copy.deepcopy(started_result)
    mismatched_first_result["job"]["state"] = "running"
    with pytest.raises(ValueError, match="queued receipt"):
        restarted.store_activation_result(
            job_id=job_id,
            capability=capability,
            idempotency_key="two-phase-activate-v1",
            result=mismatched_first_result,
        )
    type_mismatched_first_result = copy.deepcopy(started_result)
    type_mismatched_first_result["job"]["attempt"] = True
    with pytest.raises(ValueError, match="queued receipt"):
        restarted.store_activation_result(
            job_id=job_id,
            capability=capability,
            idempotency_key="two-phase-activate-v1",
            result=type_mismatched_first_result,
        )
    completed = restarted.store_activation_result(
        job_id=job_id,
        capability=capability,
        idempotency_key="two-phase-activate-v1",
        result=started_result,
    )
    assert completed == started_result
    assert restarted.activation_state(
        job_id=job_id,
        capability=capability,
        idempotency_key="two-phase-activate-v1",
    )["phase"] == "started"
    with pytest.raises(ValueError, match="queued receipt"):
        restarted.store_activation_result(
            job_id=job_id,
            capability=capability,
            idempotency_key="two-phase-activate-v1",
            result={"job": {"id": job_id, "state": "succeeded"}},
        )
    cold, _ = _fresh_installed_formal_authority(tmp_path)
    assert cold.activation_replay(
        job_id=job_id,
        capability=capability,
        idempotency_key="two-phase-activate-v1",
        companion_binding=binding,
    ) == started_result
    foreign_binding = dict(binding)
    foreign_binding["identity_sha256"] = "f" * 64
    with pytest.raises(ValueError, match=r"digest|different request"):
        cold.activation_replay(
            job_id=job_id,
            capability=capability,
            idempotency_key="two-phase-activate-v1",
            companion_binding=foreign_binding,
        )
    good_ledger = cold._read_ledger()
    corrupted_ledger = copy.deepcopy(good_ledger)
    corrupted = corrupted_ledger[capability["challenge_id"]]["activation_record"]
    corrupted["result"]["job"]["attempt"] = True
    cold._write_ledger(corrupted_ledger)
    with pytest.raises(RuntimeError, match="activation result differs"):
        _fresh_installed_formal_authority(tmp_path)
    cold._write_ledger(good_ledger)


def test_formal_activation_started_atomically_persists_exact_queued_receipt(
    tmp_path: Path,
) -> None:
    """cb53dfb8: ``started`` is never durable without its exact first receipt."""

    authority, context = _fresh_installed_formal_authority(tmp_path)
    issued = authority.issue_challenge(
        context,
        idempotency_key="atomic-started-issue-v1",
    )
    capability = issued["execution_capability"]
    job_id = capability["terminal_job_id"]
    binding = _formal_companion_binding(companion_id="atomic-started-companion")
    authority.begin_activation(
        job_id=job_id,
        capability=capability,
        idempotency_key="atomic-started-activate-v1",
        companion_binding=binding,
    )
    request_details = {
        key: value for key, value in binding.items() if key != "identity_sha256"
    }
    authority.record_activation_heartbeat(
        acknowledgment={
            "job_id": job_id,
            "challenge_id": capability["challenge_id"],
            "execution_capability": capability,
            "companion_binding": binding,
        },
        request_details=request_details,
        heartbeat={
            **request_details,
            "last_seen": NOW.isoformat(),
            "age_seconds": 0.0,
            "is_fresh": True,
        },
    )
    queued = {
        "job": {"id": job_id, "state": "queued", "attempt": 1},
        "activation_receipt": {"capability_id": capability["capability_id"]},
    }
    authority.prepare_activation_result(
        job_id=job_id,
        capability=capability,
        idempotency_key="atomic-started-activate-v1",
        result=queued,
    )

    started = authority.mark_activation_started(
        job_id=job_id,
        capability=capability,
        idempotency_key="atomic-started-activate-v1",
        result=queued,
    )
    assert started["phase"] == "started"
    assert started["started_result"] == queued
    assert started["result"] == queued
    assert authority.activation_replay(
        job_id=job_id,
        capability=capability,
        idempotency_key="atomic-started-activate-v1",
        companion_binding=binding,
    ) == queued
    wrong_type = copy.deepcopy(queued)
    wrong_type["job"]["attempt"] = True
    with pytest.raises(ValueError, match="started result differs"):
        authority.mark_activation_started(
            job_id=job_id,
            capability=capability,
            idempotency_key="atomic-started-activate-v1",
            result=wrong_type,
        )

    ledger = authority._read_ledger()
    corruptions = []
    started_null = copy.deepcopy(ledger)
    started_null[capability["challenge_id"]]["activation_record"]["result"] = None
    corruptions.append(started_null)
    missing_started = copy.deepcopy(ledger)
    del missing_started[capability["challenge_id"]]["activation_record"][
        "started_result"
    ]
    corruptions.append(missing_started)
    mismatched = copy.deepcopy(ledger)
    mismatched[capability["challenge_id"]]["activation_record"]["result"]["job"][
        "attempt"
    ] = True
    corruptions.append(mismatched)
    for broken in corruptions:
        authority._write_ledger(broken)
        with pytest.raises(RuntimeError, match=r"activation (?:result|phase)"):
            _fresh_installed_formal_authority(tmp_path)
    authority._write_ledger(ledger)


def test_formal_query_requires_job_bound_execution_capability(tmp_path: Path) -> None:
    """Ordinary same-shape traffic cannot enter the active formal ledger."""

    from tripchord.providers.browser_bridge import (
        BrowserProvider,
        BrowserTaskBridge,
        BrowserTaskSubmission,
        BrowserVertical,
    )

    authority, context = _fresh_installed_formal_authority(tmp_path)
    issued = authority.issue_challenge(
        context,
        idempotency_key="formal-capability-1",
    )
    graph = context["job_graph"]
    assert isinstance(graph, dict)
    pair = graph["pairs"][0]
    task_id = next(
        item
        for item in pair["query_task_ids"]
        if item.startswith("query:ctrip:flight:")
    )
    query = {
        "origin": "杭州",
        "destination": "马累",
        "start_date": pair["departure_date"],
        "end_date": pair["return_date"],
        "adults": graph["adults"],
        "rooms": 1,
        "currency": "CNY",
        "origin_code": "HGH",
        "destination_code": "MLE",
        "search_url": (
            "https://flights.ctrip.com/international/search/round-hgh-mle"
            f"?depdate={pair['departure_date']}_{pair['return_date']}"
            f"&cabin=y_s&adult={graph['adults']}&child=0&infant=0"
        ),
        "options": {},
    }

    with pytest.raises(ValueError, match="execution capability"):
        authority.formal_browser_query(
            task_id="browser-task-ordinary",
            provider="ctrip",
            kind="flight",
            query=query,
        )

    with authority.execution_scope(issued["execution_capability"]):
        formal = authority.formal_browser_query(
            task_id="browser-task-formal",
            provider="ctrip",
            kind="flight",
            query=query,
        )
    assert formal["query_task_id"] == task_id

    foreign = dict(issued["execution_capability"])
    foreign["terminal_job_id"] = "live-job-foreign"
    with (
        pytest.raises(ValueError, match="execution capability"),
        authority.execution_scope(foreign),
    ):
        authority.formal_browser_query(
            task_id="browser-task-foreign",
            provider="ctrip",
            kind="flight",
            query=query,
        )

    bridge = BrowserTaskBridge(source_authority=authority)
    submission = BrowserTaskSubmission.model_validate(
        {
            "provider": BrowserProvider.CTRIP,
            "kind": BrowserVertical.FLIGHT,
            "query": query,
            "reuse_partition_sha256": "a" * 64,
        }
    )
    async def submit_interleaved() -> tuple[object, object, object, object]:
        ordinary = (await bridge.submit_many((submission,)))[0]
        with authority.execution_scope(issued["execution_capability"]):
            scoped = (await bridge.submit_many((submission,)))[0]
        return (
            ordinary,
            scoped,
            await bridge.formal_execution_capability(ordinary.id),
            await bridge.formal_execution_capability(scoped.id),
        )

    ordinary, scoped, ordinary_capability, scoped_capability = asyncio.run(
        submit_interleaved()
    )
    assert ordinary.id != scoped.id
    assert ordinary_capability is None
    assert scoped_capability == issued["execution_capability"]


def test_formal_browser_task_capability_survives_bridge_cold_restart(
    tmp_path: Path,
) -> None:
    """92a0db1a: a restarted bridge cannot detach a task from its signed job."""

    from tripchord.providers.browser_bridge import (
        BrowserProvider,
        BrowserTaskBridge,
        BrowserTaskSubmission,
        BrowserVertical,
        JsonFileBrowserBridgeStateStore,
    )

    authority, context = _fresh_installed_formal_authority(tmp_path)
    issued = authority.issue_challenge(
        context,
        idempotency_key="persisted-browser-capability-v1",
    )
    graph = context["job_graph"]
    assert isinstance(graph, dict)
    pair = graph["pairs"][0]
    query = {
        "origin": "杭州",
        "destination": "马累",
        "start_date": pair["departure_date"],
        "end_date": pair["return_date"],
        "adults": graph["adults"],
        "rooms": 1,
        "currency": "CNY",
        "origin_code": "HGH",
        "destination_code": "MLE",
        "search_url": (
            "https://flights.ctrip.com/international/search/round-hgh-mle"
            f"?depdate={pair['departure_date']}_{pair['return_date']}"
            f"&cabin=y_s&adult={graph['adults']}&child=0&infant=0"
        ),
        "options": {},
    }
    submission = BrowserTaskSubmission.model_validate(
        {
            "provider": BrowserProvider.CTRIP,
            "kind": BrowserVertical.FLIGHT,
            "query": query,
            "reuse_partition_sha256": "7" * 64,
        }
    )
    store = JsonFileBrowserBridgeStateStore(tmp_path / "browser-state.json")
    bridge = BrowserTaskBridge(
        state_store=store,
        source_authority=authority,
        now=lambda: NOW,
    )

    async def submit() -> str:
        with authority.execution_scope(issued["execution_capability"]):
            return (await bridge.submit_many((submission,)))[0].id

    task_id = asyncio.run(submit())
    restarted = BrowserTaskBridge(
        state_store=store,
        source_authority=authority,
        now=lambda: NOW,
    )
    assert asyncio.run(restarted.formal_execution_capability(task_id)) == issued[
        "execution_capability"
    ]


