    async def exercise_fault() -> None:
        first_process = await start_server(1, fault=fault_mode)
        async with httpx.AsyncClient(timeout=30.0) as client:
            runtime = (await client.get(f"{base}/api/v1/agents/runtime")).json()[
                "runtime_provenance"
            ]
