def test_formal_source_compact_summary_is_minimal_and_cross_swap_safe() -> None:
    from tripchord.formal_live_source import (
        formal_source_evidence_summary,
        validate_formal_source_summary,
    )

    binding = _fixture_formal_source_binding()
    challenge = binding["challenge"]
    assert isinstance(challenge, dict)
    expected = {
        key: challenge[key]
        for key in (
            "run_id",
            "tested_commit_sha",
            "runtime_identity",
            "request_sha256",
            "candidate_set_sha256",
            "scenario_sha256",
            "job_graph",
        )
    }
    summary = formal_source_evidence_summary(
        binding,
        binding["authority_receipt"],
        challenge,
        expected_context=expected,
    )
    forbidden = {
        "binding",
        "receipts",
        "completion",
        "snapshot",
        "visible_evidence",
        "runtime_identity",
    }
    assert not (forbidden & set(summary))
    assert "/repo" not in json.dumps(summary)
    validate_formal_source_summary(summary, expected_context=expected)

    other = _fixture_formal_source_binding(
        install_id="00000000-0000-4000-8000-000000000099"
    )
    other_summary = formal_source_evidence_summary(
        other,
        other["authority_receipt"],
        other["challenge"],
        expected_context=expected,
    )
    mutations = []
    swapped = copy.deepcopy(summary)
    swapped["binding_digest"] = other_summary["binding_digest"]
    mutations.append(swapped)
    missing = copy.deepcopy(summary)
    missing.pop("delta_digest")
    mutations.append(missing)
    extra = copy.deepcopy(summary)
    extra["binding"] = binding
    mutations.append(extra)
    wrong = copy.deepcopy(summary)
    wrong["runtime_identity_sha256"] = "f" * 64
    mutations.append(wrong)
    for mutation in mutations:
        with pytest.raises(ValueError):
            validate_formal_source_summary(mutation, expected_context=expected)


def _reseal_test_formal_binding(binding: dict[str, object]) -> dict[str, object]:
    import base64

    from cryptography.hazmat.primitives import serialization
    from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey
    from tripchord.formal_live_source import _receipt_proof_payload

    assert _TEST_FORMAL_PRIVATE_KEY_PATH is not None
    loaded = serialization.load_pem_private_key(
        _TEST_FORMAL_PRIVATE_KEY_PATH.read_bytes(),
        password=None,
    )
    assert isinstance(loaded, Ed25519PrivateKey)

    def digest(value: object) -> str:
        return hashlib.sha256(
            json.dumps(
                value,
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            ).encode()
        ).hexdigest()

    def sign(value: object) -> str:
        raw = json.dumps(
            value,
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        ).encode()
        return base64.b64encode(loaded.sign(raw)).decode()

    candidate = copy.deepcopy(binding)
    events = candidate["receipts"]
    assert isinstance(events, list)
    previous = str(candidate["composition_sha256"])
    for event in events:
        assert isinstance(event, dict)
        event["previous_receipt_sha256"] = previous
        unsigned = {
            key: value
            for key, value in event.items()
            if key not in {"receipt_sha256", "signature"}
        }
        event["receipt_sha256"] = digest(unsigned)
        event["signature"] = sign(
            {
                "purpose": "tripchord-formal-live-source-event-v3",
                "receipt_sha256": event["receipt_sha256"],
            }
        )
        previous = str(event["receipt_sha256"])
    candidate["companion_heartbeat_receipt"] = copy.deepcopy(events[0])
    candidate["post_chain_sha256"] = previous
    candidate["post_event_count"] = len(events)
    unsigned_binding = {
        key: value
        for key, value in candidate.items()
        if key not in {"binding_digest", "authority_receipt"}
    }
    candidate["binding_digest"] = digest(unsigned_binding)
    receipt = candidate["authority_receipt"]
    assert isinstance(receipt, dict)
    receipt["binding_digest"] = candidate["binding_digest"]
    receipt["post_event_count"] = len(events)
    receipt["delta_digest"] = digest(events)
    receipt["signature"] = sign(_receipt_proof_payload(receipt))
    return candidate


def test_formal_source_full_reseal_rejects_untrusted_executor() -> None:
    """Even an authority-resealed raw binding cannot bless a non-extension source."""

    from tripchord.formal_live_source import validate_formal_source_evidence

    binding = copy.deepcopy(_fixture_formal_source_binding())
    receipts = binding["receipts"]
    assert isinstance(receipts, list)
    for event in receipts:
        if not isinstance(event, dict) or event.get("kind") != "browser_complete":
            continue
        details = event["details"]
        source_receipt = details["source_execution_receipt"]
        source_receipt["execution_environment"] = "untrusted_external_executor"
        source_receipt["receipt_sha256"] = _c4_canonical_sha256(
            {
                key: value
                for key, value in source_receipt.items()
                if key != "receipt_sha256"
            }
        )

    resealed = _reseal_test_formal_binding(binding)
    with pytest.raises(ValueError, match="execution_environment"):
        validate_formal_source_evidence(resealed)


def test_formal_source_full_reseal_rejects_sensitive_search_url() -> None:
    from tripchord.formal_live_source import validate_formal_source_evidence

    binding = copy.deepcopy(_fixture_formal_source_binding())
    receipts = binding["receipts"]
    assert isinstance(receipts, list)
    claim = next(event for event in receipts if event["kind"] == "browser_claim")
    lease = next(
        item
        for item in claim["details"]["leases"]
        if item["kind"] == "flight"
    )
    task_id = lease["task_id"]
    malicious = "https://flights.ctrip.com/international/search/round-hgh-mle?token=secret"
    lease["query"]["search_url"] = malicious
    formal = lease["formal_query"]
    formal["query_sha256"] = _c4_canonical_sha256(lease["query"])
    formal["query_identity"] = _c4_canonical_sha256(
        {key: value for key, value in formal.items() if key != "query_identity"}
    )
    completion = next(
        event
        for event in receipts
        if event["kind"] == "browser_complete"
        and event["details"]["task_id"] == task_id
    )
    completion["details"]["snapshot"]["query"] = copy.deepcopy(lease["query"])
    completion["details"]["formal_query"] = copy.deepcopy(formal)
    completion["details"]["result_sha256"] = _c4_canonical_sha256(
        completion["details"]["snapshot"]
    )
    resealed = _reseal_test_formal_binding(binding)
    with pytest.raises(ValueError, match="exact public search URL"):
        validate_formal_source_evidence(resealed)
    raw = json.dumps(
        {
            "formal_live_source_binding": resealed,
            "formal_live_source_authority_receipt": resealed["authority_receipt"],
            "formal_live_source_challenge": resealed["challenge"],
        }
    ).encode()
    with pytest.raises(gate.GateStateChangedError, match="secret leak"):
        gate._secret_scan_bytes(
            raw,
            gate._SecretNeedles(()),
            "evidence",
            "full-reseal.failure.json",
        )


