def test_r42_block85_legal_language_recursive_json_five_route(
    tmp_path: Path,
) -> None:
    r"""C-122 round-42 Block 85 (打回七): a legal-language phrase re-encoded
    with ``json.dumps`` 2/3/4 times — ``(plannerV2) is a version.``, the TAB
    narration ``(plannerV2) is<TAB>a version.``, ``plannerV2 isn't active`` and
    ``plannerV2 is a non-secret version`` — was misjudged by the Block 84
    walker as a WRAPPED exact base at decode L1: the outer JSON text
    ``"(plannerV2) is a version."`` opens AND closes with ``"`` and carries the
    base, so ``_registered_base_value_info`` resolved it to ``('planner',
    True)`` and the outer level was REJECTED by both finals / masked by the
    producer (Block 84 only judged the DECODED value, never re-decoding the
    outer JSON text first).

    The Block 85 fix DEFERS the registered-base judgment while the decoded
    scalar is STILL JSON text: recurse to the REAL inner value FIRST, then
    judge it at the carried path — ``"..."`` -> ``(plannerV2) is a version.`` ->
    phrase (exempt).  All four legal phrases at depth 2/3/4 are accepted by
    all FIVE routes (raw committed/failure finals accept, producer leaves the
    value untouched, real 0600 seal -> consumer committed/failure finals
    accept); the Block 84 exact / balanced-wrapped / provider / Unicode-
    escaped negatives and the Block 61 decoded negatives keep failing closed
    on the raw routes and stay producer-masked.
    """
    from benchmarks import live_canary_certified as canary

    def layered(base: str, n: int) -> str:
        s = base
        for _ in range(n):
            s = json.dumps(s)
        return s

    def final(raw: str, label: str, field_check: bool) -> None:
        gate._secret_scan_bytes(
            raw.encode(),
            gate._SecretNeedles(()),
            "evidence",
            label,
            credential_field_check=field_check,
        )

    def sealed_accepts(masked: str, run_id: str) -> None:
        """Real 0600 seal + consumer-synthesized field both accept the
        artifact (the producer masked / left it BEFORE the seal)."""
        output = tmp_path / "live-canary-certified.json"
        diag = canary._seal_failure_diagnostic(
            "evaluate",
            RuntimeError(masked),
            output,
            run_id=run_id,
            tested_sha="9" * 40,
        )
        assert stat.S_IMODE(diag.stat().st_mode) == 0o600
        gate._secret_scan_bytes(
            diag.read_bytes(),
            gate._SecretNeedles(()),
            "evidence",
            "live-canary-certified.json.failure.json",
            credential_field_check=False,
        )
        gate._secret_scan_bytes(
            gate._sanitize_canary_diag_field(
                json.dumps({"summary": masked}), "fallback"
            ).encode(),
            gate._SecretNeedles(()),
            "evidence",
            "ev.json",
            credential_field_check=True,
        )

    # Block 85 positives: the four legal-language phrases re-encoded 2/3/4
    # times must be accepted by BOTH finals, left UNTOUCHED by the producer,
    # and accepted through the real 0600 seal + consumer field.
    b85_pos = tuple(
        layered(base, n)
        for base in (
            "(plannerV2) is a version.",
            "(plannerV2) is\ta version.",  # real TAB (json.dumps -> \t)
            "plannerV2 isn't active",
            "plannerV2 is a non-secret version",
        )
        for n in (2, 3, 4)
    )
    for raw in b85_pos:
        final(raw, "ev.json", True)
        final(raw, "live-canary-certified.json.failure.json", False)
        masked = canary._desensitize(raw)
        assert "[REDACTED]" not in masked, raw
        sealed_accepts(masked, "r42b85")

    # Block 84 negatives preserved: an exact / balanced-wrapped / provider /
    # Unicode-escaped base re-encoded 2/3/4 times still fails both finals and
    # is masked WHOLE by the producer, so the sealed diagnostic and the
    # consumer field only pass because the producer already masked.
    b84_neg = tuple(
        layered(base, n)
        for base in ("plannerV2", "(plannerV2)", "providerV4", "[providerV4]")
        for n in (2, 3, 4)
    ) + tuple(layered('"\\u0070lannerV2"', n) for n in (1, 2, 3))
    for raw in b84_neg:
        with pytest.raises(gate.GateStateChangedError):
            final(raw, "ev.json", True)
        with pytest.raises(gate.GateStateChangedError):
            final(raw, "live-canary-certified.json.failure.json", False)
        masked = canary._desensitize(raw)
        assert "[REDACTED]" in masked, raw
        assert "plannerV2" not in masked and "providerV4" not in masked, raw
        sealed_accepts(masked, "r42b85")

    # Block 61 decoded negative preserved: an UNBOUND key inside a decoded
    # dict level still fails closed on both finals and is producer-masked.
    decoded_neg = '{"summary": "{\\"otp\\": \\"plannerV2\\"}"}'
    with pytest.raises(gate.GateStateChangedError):
        final(decoded_neg, "ev.json", True)
    with pytest.raises(gate.GateStateChangedError):
        final(decoded_neg, "live-canary-certified.json.failure.json", False)
    masked = canary._desensitize(decoded_neg)
    assert "[REDACTED]" in masked
    sealed_accepts(masked, "r42b85")


def test_r42_block86_encoded_array_per_item_path_five_route(
    tmp_path: Path,
) -> None:
    r"""C-122 round-42 Block 86 (打回七): an ARRAY re-encoded with
    ``json.dumps`` 2/3/4 times laundered a registered base through the decode
    recursion at EVERY position but the first — the Block 84 walker judged
    direct array ELEMENTS only at ``depth == 0`` with paths RESET to ``()``,
    so a decoded array at depth >= 1 had its items never judged (depth 2/3/4
    ``["x", "plannerV2", "y"]`` -> middle / last / nested launder through the
    raw committed + failure finals).

    The Block 86 fix carries the member path through the decode recursion for
    LIST levels (list items sit at ``(carried_path, "[]", ...)``) and judges
    EVERY decoded item per its carried path, so an exact / balanced-wrapped /
    provider base at FIRST / MIDDLE / LAST / NESTED position, depth 2/3/4,
    fails closed on both raw finals and is masked WHOLE by the producer; the
    real 0600 seal -> consumer dual finals accept ONLY because the producer
    already masked.  The same positions with a legal-language phrase
    (``["x", "(plannerV2) is a version.", "y"]`` /
    ``["x", "plannerV2 is a non-secret version", "y"]``) are accepted by all
    five routes and left producer-untouched.  A documented OUTER member
    inherits the exemption for its decoded array elements
    (``("planner_version", "[]")`` -> ``("planner_version",)`` ->
    ``planner`` allowed), so ``{"planner_version": "[plannerV2]"}`` /
    ``"[[plannerV2]]"`` / ``"[\"plannerV2\"]"`` / ``"[[\"plannerV2\"]]"`` /
    ``{"plan": {"planner_version": "[plannerV2]"}}`` and the free-form
    ``{"summary": "[\"plannerV2\", \"providerV4\"]"}`` are finals-accepted,
    while a cross-field element (``planner_version`` + ``providerV4``) and an
    UNBOUND element (``("otp", "[]")`` / ``("otp",)`` + ``"[plannerV2]"``)
    fail closed on both finals.  Block 65 / Block 84 finals are preserved.
    """
    from benchmarks import live_canary_certified as canary

    def layered(base: str, n: int) -> str:
        s = base
        for _ in range(n):
            s = json.dumps(s)
        return s

    def final(raw: str, label: str, field_check: bool) -> None:
        gate._secret_scan_bytes(
            raw.encode(),
            gate._SecretNeedles(()),
            "evidence",
            label,
            credential_field_check=field_check,
        )

    def rejects(raw: str) -> None:
        with pytest.raises(gate.GateStateChangedError):
            final(raw, "ev.json", True)
        with pytest.raises(gate.GateStateChangedError):
            final(raw, "live-canary-certified.json.failure.json", False)

    def accepts(raw: str) -> None:
        final(raw, "ev.json", True)
        final(raw, "live-canary-certified.json.failure.json", False)

    def sealed_accepts(masked: str, run_id: str) -> None:
        output = tmp_path / "live-canary-certified.json"
        diag = canary._seal_failure_diagnostic(
            "evaluate",
            RuntimeError(masked),
            output,
            run_id=run_id,
            tested_sha="9" * 40,
        )
        assert stat.S_IMODE(diag.stat().st_mode) == 0o600
        gate._secret_scan_bytes(
            diag.read_bytes(),
            gate._SecretNeedles(()),
            "evidence",
            "live-canary-certified.json.failure.json",
            credential_field_check=False,
        )
        gate._secret_scan_bytes(
            gate._sanitize_canary_diag_field(
                json.dumps({"summary": masked}), "fallback"
            ).encode(),
            gate._SecretNeedles(()),
            "evidence",
            "ev.json",
            credential_field_check=True,
        )

    # Block 86 negatives: an exact / balanced-wrapped / provider base at
    # FIRST / MIDDLE / LAST / NESTED array position, re-encoded 2/3/4 times.
    b86_reject = tuple(
        layered(arr, n)
        for base in ("plannerV2", "(plannerV2)", "providerV4")
        for n in (2, 3, 4)
        for arr in (
            f"[{json.dumps(base)}, \"x\", \"y\"]",
            f"[\"x\", {json.dumps(base)}, \"y\"]",
            f"[\"x\", \"y\", {json.dumps(base)}]",
            f"[\"x\", [{json.dumps(base)}]]",
        )
    )
    for raw in b86_reject:
        rejects(raw)
        masked = canary._desensitize(raw)
        assert "[REDACTED]" in masked, raw
        assert "plannerV2" not in masked and "providerV4" not in masked, raw
        sealed_accepts(masked, "r42b86")

    # Same-position legal prose: five-route accept, producer-untouched.
    b86_prose = tuple(
        layered(arr, n)
        for n in (2, 3, 4)
        for arr in (
            '["x", "(plannerV2) is a version.", "y"]',
            '["x", "plannerV2 is a non-secret version", "y"]',
        )
    )
    for raw in b86_prose:
        accepts(raw)
        masked = canary._desensitize(raw)
        assert "[REDACTED]" not in masked, raw
        sealed_accepts(masked, "r42b86")

    # Documented-outer-member array semantics (finals; the producer
    # conservatively over-masks the inner decoded item in several of these).
    doc_pos = (
        '{"planner_version": "[plannerV2]"}',
        '{"planner_version": "[[plannerV2]]"}',
        '{"planner_version": "[\\"plannerV2\\"]"}',
        '{"planner_version": "[[\\"plannerV2\\"]]"}',
        '{"plan": {"planner_version": "[plannerV2]"}}',
        '{"summary": "[\\"plannerV2\\", \\"providerV4\\"]"}',
    )
    doc_neg = (
        '{"planner_version": "[providerV4]"}',
        '{"planner_version": "[\\"providerV4\\"]"}',
        '{"otp": "[plannerV2]"}',
        '{"otp": "[\\"plannerV2\\"]"}',
        '{"otp": "[[\\"plannerV2\\"]]"}',
        '{"otp": "\\"[plannerV2]\\""}',
    )
    for raw in doc_pos:
        accepts(raw)
    for raw in doc_neg:
        rejects(raw)

    # Block 65 / 84 finals preserved for the top-level TAB-prose array, nested
    # arrays and the documented direct values.
    preserved = (
        '["x", "(plannerV2) is\\ta version.", "y"]',
        '{"a": ["x", "(plannerV2) is\\ta version.", "y"]}',
        '{"a": [["(plannerV2) is\\ta version."]]}',
        '{"summary": "plannerV2"}',
        '{"planner_version": "plannerV2"}',
    )
    for raw in preserved:
        accepts(raw)


def test_r42_block87_typed_array_marker_five_route(
    tmp_path: Path,
) -> None:
    r"""C-122 round-42 Block 87 (打回八): the shared exact-path matcher
    ``_registered_base_value_exempt_at_path`` stripped EVERY trailing string
    path segment equal to ``"[]"``, conflating a REAL JSON object member KEY
    literally named ``"[]"`` (``{"planner_version": {"[]": "plannerV2"}}``)
    with the array-element marker a list item appends.  A documented outer
    member (``("planner_version", "[]")`` -> ``("planner_version",)``) then
    inherited the exemption for a value sitting at the genuine ``"[]"`` key,
    and the free-text assignment helper (``planner_version.[] = plannerV2``)
    laundered an EXACT base through the documented prefix — raw committed +
    failure dual finals ACCEPTED, the producer left it UNTOUCHED.

    The fix makes the array marker a TYPED sentinel (``_ARRAY_PATH_ELEMENT``):
    a real ``"[]"`` member key is a STRING segment the matcher never strips, so
    the unescaped/escaped dict-key / documented-prefix / summary / nested /
    pseudo-path JSON forms AND the dotted assignment fields (``.[] =``) fail
    closed on both raw finals while the producer masks whole; the sealed 0600
    diagnostic -> consumer dual finals accept ONLY because the producer already
    masked.  A truly documented outer ARRAY / nested-ARRAY element (the
    string-encoded ``{"planner_version": "[plannerV2]"}`` family and a real
    array element not bound at the ``:``) still keeps the exemption and is
    finals-accepted (Block 86 positives preserved).
    """
    from benchmarks import live_canary_certified as canary

    def final(raw: str, label: str, field_check: bool) -> None:
        gate._secret_scan_bytes(
            raw.encode(),
            gate._SecretNeedles(()),
            "evidence",
            label,
            credential_field_check=field_check,
        )

    def rejects(raw: str) -> None:
        with pytest.raises(gate.GateStateChangedError):
            final(raw, "ev.json", True)
        with pytest.raises(gate.GateStateChangedError):
            final(raw, "live-canary-certified.json.failure.json", False)

    def accepts(raw: str) -> None:
        final(raw, "ev.json", True)
        final(raw, "live-canary-certified.json.failure.json", False)

    def sealed_accepts(masked: str, run_id: str) -> None:
        output = tmp_path / "live-canary-certified.json"
        diag = canary._seal_failure_diagnostic(
            "evaluate",
            RuntimeError(masked),
            output,
            run_id=run_id,
            tested_sha="9" * 40,
        )
        assert stat.S_IMODE(diag.stat().st_mode) == 0o600
        gate._secret_scan_bytes(
            diag.read_bytes(),
            gate._SecretNeedles(()),
            "evidence",
            "live-canary-certified.json.failure.json",
            credential_field_check=False,
        )
        gate._secret_scan_bytes(
            gate._sanitize_canary_diag_field(
                json.dumps({"summary": masked}), "fallback"
            ).encode(),
            gate._SecretNeedles(()),
            "evidence",
            "ev.json",
            credential_field_check=True,
        )

    # Block 87 negatives — a genuine ``"[]"`` MEMBER KEY (unescaped /
    # escaped), under a documented prefix / summary / nested / pseudo-path, and
    # the free-text assignment field ``<documented>.[] = <base>`` all fail
    # closed on both raw finals; the producer masks; the sealed + consumer dual
    # finals accept only because the producer already masked.
    b87_reject = (
        # unescaped / escaped literal ``"[]"`` object keys under a documented
        # member (the supervisor's repro shapes).
        '{"planner_version":{"[]":"plannerV2"}}',
        '{"planner_version":{"\\u005b\\u005d":"plannerV2"}}',
        '{"planner_version":{"\\u005B\\u005D":"plannerV2"}}',
        '{"summary":{"[]":"plannerV2"}}',
        '{"summary":{"[]":"providerV4"}}',
        # nested / deeper ``"[]"`` keys.
        '{"plan":{"planner_version":{"[]":"plannerV2"}}}',
        '{"planner_version":{"x":{"[]":"plannerV2"}}}',
        '{"summary":{"[]":{"[]":"plannerV2"}}}',
        # pseudo / unbound paths.
        '{"evilplanner_version":{"[]":"plannerV2"}}',
        '{"otp":{"[]":"plannerV2"}}',
        '{"planner_version":{"[]":"providerV4"}}',
        # assignment / helper callers — a dotted documented field ending in
        # ``.[]`` binds an exact base into the laundered documented prefix.
        "planner_version.[] = plannerV2",
        "plan.planner_version.[] = plannerV2",
        "summary.[] = plannerV2",
        "planner_version.[] = providerV4",
    )
    for raw in b87_reject:
        rejects(raw)
        masked = canary._desensitize(raw)
        assert "[REDACTED]" in masked, raw
        sealed_accepts(masked, "r42b87")

    # Block 87 positives — a truly documented outer ARRAY / nested-ARRAY
    # element still inherits the exemption and is finals-accepted (Block 86
    # ``doc_pos`` preserved).
    b87_pos = (
        '{"planner_version":"[plannerV2]"}',
        '{"planner_version":"[[plannerV2]]"}',
        '{"planner_version":"[\\"plannerV2\\"]"}',
        '{"planner_version":"[[\\"plannerV2\\"]]"}',
        '{"plan":{"planner_version":"[plannerV2]"}}',
        '{"summary":"[\\"plannerV2\\", \\"providerV4\\"]"}',
        '{"planner_version":["x","plannerV2","y"]}',
    )
    for raw in b87_pos:
        accepts(raw)


def test_r42_block86_prose_position_matrix_and_unicode_bracket_negatives(
    tmp_path: Path,
) -> None:
    r"""C-122 round-42 Block 86 matrix completion (打回八 要求 2): the earlier
    Block 86 prose positives only exercised the MIDDLE array position; a legal
    language phrase must be accepted at FIRST / MIDDLE / LAST / NESTED positions
    through every decode depth (2/3/4) on all five routes, producer-untouched.
    The negative matrix additionally covers a bracket-wrapped registered base
    (``[providerV4]``) and a Unicode-escaped spelling of a base
    (``providerV4``) as array elements — the exact-base family (Block 86
    ``b86_reject`` already asserts ``plannerV2`` / ``(plannerV2)`` /
    ``providerV4`` at every position) — all failing closed on both raw finals
    with the producer masking, and the sealed 0600 diagnostic -> consumer dual
    finals accepting only the already-masked producer output.
    """
    from benchmarks import live_canary_certified as canary

    def layered(base: str, n: int) -> str:
        s = base
        for _ in range(n):
            s = json.dumps(s)
        return s

    def final(raw: str, label: str, field_check: bool) -> None:
        gate._secret_scan_bytes(
            raw.encode(),
            gate._SecretNeedles(()),
            "evidence",
            label,
            credential_field_check=field_check,
        )

    def rejects(raw: str) -> None:
        with pytest.raises(gate.GateStateChangedError):
            final(raw, "ev.json", True)
        with pytest.raises(gate.GateStateChangedError):
            final(raw, "live-canary-certified.json.failure.json", False)

    def accepts(raw: str) -> None:
        final(raw, "ev.json", True)
        final(raw, "live-canary-certified.json.failure.json", False)

    def sealed_accepts(masked: str, run_id: str) -> None:
        output = tmp_path / "live-canary-certified.json"
        diag = canary._seal_failure_diagnostic(
            "evaluate",
            RuntimeError(masked),
            output,
            run_id=run_id,
            tested_sha="9" * 40,
        )
        assert stat.S_IMODE(diag.stat().st_mode) == 0o600
        gate._secret_scan_bytes(
            diag.read_bytes(),
            gate._SecretNeedles(()),
            "evidence",
            "live-canary-certified.json.failure.json",
            credential_field_check=False,
        )
        gate._secret_scan_bytes(
            gate._sanitize_canary_diag_field(
                json.dumps({"summary": masked}), "fallback"
            ).encode(),
            gate._SecretNeedles(()),
            "evidence",
            "ev.json",
            credential_field_check=True,
        )

    # Legal prose at FIRST / MIDDLE / LAST / NESTED array positions, re-encoded
    # 2/3/4 times: accepted by all five routes, producer-untouched.
    b86_prose_matrix = tuple(
        layered(arr, n)
        for n in (2, 3, 4)
        for arr in (
            '["(plannerV2) is a version.", "x", "y"]',
            '["x", "(plannerV2) is a version.", "y"]',
            '["x", "y", "(plannerV2) is a version."]',
            '["x", ["(plannerV2) is a version."]]',
            '["plannerV2 is a non-secret version", "x", "y"]',
            '["x", "plannerV2 is a non-secret version", "y"]',
            '["x", "y", "plannerV2 is a non-secret version"]',
            '["x", ["plannerV2 is a non-secret version"]]',
        )
    )
    for raw in b86_prose_matrix:
        accepts(raw)
        masked = canary._desensitize(raw)
        assert "[REDACTED]" not in masked, raw
        sealed_accepts(masked, "r42b86m")

    # Bracket-wrapped ``[providerV4]`` and Unicode-escaped base array elements
    # (``providerV4``) at FIRST / MIDDLE / NESTED positions, depth 2/3/4:
    # both raw finals reject, the producer masks, the sealed + consumer dual
    # finals accept only the masked producer output.
    b86_neg_matrix = tuple(
        layered(arr, n)
        for n in (2, 3, 4)
        for arr in (
            '["x", "[providerV4]", "y"]',
            '["[providerV4]", "x", "y"]',
            '["x", ["[providerV4]"]]',
            '["x", "\\u0070roviderV4", "y"]',
            '["\\u0070roviderV4", "x", "y"]',
            '["x", ["\\u0070roviderV4"]]',
        )
    )
    for raw in b86_neg_matrix:
        rejects(raw)
        masked = canary._desensitize(raw)
        assert "[REDACTED]" in masked, raw
        assert "providerV4" not in masked, raw
        sealed_accepts(masked, "r42b86m")


def test_r42_block88_documented_real_array_position_independent_five_route(
    tmp_path: Path,
) -> None:
    r"""C-122 round-42 Block 88 (打回九): a DOCUMENTED outer member's REAL ARRAY
    (not the string-encoded form) made the documented exemption
    POSITION-DEPENDENT — a registered base at the FIRST array element
    (``{"planner_version":["plannerV2","x","y"]}``) was rejected by both raw
    finals and masked WHOLE by the producer, while MIDDLE / LAST were accepted
    and retained.  The free-text narration backstop misread the first element's
    ``["plannerV2"`` token as a tight prose wrapper (WRAPPED_BASE_ILLEGAL)
    instead of the JSON document's own array structure, so the raw-final scan
    and the producer's final-sweep masker both fired on a value the JSON walker
    (and the contract) exempt.

    The fix judges the WRAPPED_BASE_ILLEGAL token as a genuine JSON array
    element at the carried ARRAY path — exactly like the JSON walker does — so
    the documented exemption is POSITION-INDEPENDENT: FIRST / MIDDLE / LAST /
    NESTED and every decode depth (the real JSON layer plus 2/3/4
    ``json.dumps`` encodings) accept on all five routes with the producer
    leaving the element UNTOUCHED.  Cross-field and unbound bases at ANY
    position still fail closed on both raw finals with the producer masking,
    and the sealed 0600 diagnostic -> consumer dual finals accept ONLY the
    already-masked producer output.  The Block 87 ``"[]"`` member-key / pseudo-
    path / assignment-helper counterexamples are preserved verbatim (a string
    key ``'[]'`` is never an array marker).
    """
    from benchmarks import live_canary_certified as canary

    def layered(base: str, n: int) -> str:
        s = base
        for _ in range(n):
            s = json.dumps(s)
        return s

    def final(raw: str, label: str, field_check: bool) -> None:
        gate._secret_scan_bytes(
            raw.encode(),
            gate._SecretNeedles(()),
            "evidence",
            label,
            credential_field_check=field_check,
        )

    def rejects(raw: str) -> None:
        with pytest.raises(gate.GateStateChangedError):
            final(raw, "ev.json", True)
        with pytest.raises(gate.GateStateChangedError):
            final(raw, "live-canary-certified.json.failure.json", False)

    def accepts(raw: str) -> None:
        final(raw, "ev.json", True)
        final(raw, "live-canary-certified.json.failure.json", False)

    def sealed_accepts(masked: str, run_id: str) -> None:
        output = tmp_path / "live-canary-certified.json"
        diag = canary._seal_failure_diagnostic(
            "evaluate",
            RuntimeError(masked),
            output,
            run_id=run_id,
            tested_sha="9" * 40,
        )
        assert stat.S_IMODE(diag.stat().st_mode) == 0o600
        gate._secret_scan_bytes(
            diag.read_bytes(),
            gate._SecretNeedles(()),
            "evidence",
            "live-canary-certified.json.failure.json",
            credential_field_check=False,
        )
        gate._secret_scan_bytes(
            gate._sanitize_canary_diag_field(
                json.dumps({"summary": masked}), "fallback"
            ).encode(),
            gate._SecretNeedles(()),
            "evidence",
            "ev.json",
            credential_field_check=True,
        )

    # Block 88 positives — a DOCUMENTED outer member's real array, base at
    # FIRST / MIDDLE / LAST / NESTED (single, nested-array, nested deeper), for
    # the planner AND provider documented bases and the documented ``plan.``
    # prefix + ``summary`` free-text contract: accepted by all five routes,
    # producer-untouched (no ``[REDACTED]``).
    doc_pos = (
        '{"planner_version":["plannerV2","x","y"]}',
        '{"planner_version":["x","plannerV2","y"]}',
        '{"planner_version":["x","y","plannerV2"]}',
        '{"planner_version":["plannerV2"]}',
        '{"planner_version":[["plannerV2"]]}',
        '{"planner_version":[["x"],["plannerV2"]]}',
        '{"planner_version":[["x"],["y"],["plannerV2"]]}',
        '{"planner_version":[[["plannerV2"]]]}',
        '{"provider_version":["providerV4","x","y"]}',
        '{"provider_version":["x","providerV4","y"]}',
        '{"provider_version":["x","y","providerV4"]}',
        '{"plan":{"planner_version":["plannerV2","x"]}}',
        '{"plan":{"provider_version":["providerV4","x"]}}',
        '{"summary":["plannerV2","x"]}',
        '{"summary":["x","providerV4","y"]}',
    )
    for raw in doc_pos:
        accepts(raw)
        masked = canary._desensitize(raw)
        assert "[REDACTED]" not in masked, raw
        sealed_accepts(masked, "r42b88p")

    # Same documented-real-array positions re-encoded 2/3/4 times: the path is
    # carried through the decode recursion, so every depth accepts and the
    # producer stays untouched.
    doc_pos_layered = tuple(
        layered(arr, n)
        for n in (2, 3, 4)
        for arr in (
            '{"planner_version":["plannerV2","x","y"]}',
            '{"planner_version":["x","plannerV2","y"]}',
            '{"planner_version":["x","y","plannerV2"]}',
            '{"planner_version":["x",["plannerV2"],"y"]}',
            '{"planner_version":["x",["y",["plannerV2"]]]}',
            '{"plan":{"planner_version":["plannerV2","x"]}}',
            '{"provider_version":["providerV4","x","y"]}',
            '{"summary":["plannerV2","x"]}',
        )
    )
    for raw in doc_pos_layered:
        accepts(raw)
        masked = canary._desensitize(raw)
        assert "[REDACTED]" not in masked, raw
        sealed_accepts(masked, "r42b88p")

    # Block 88 negatives — a cross-field / unbound base (bracket-wrapped
    # ``[providerV4]`` and the Unicode-escaped spelling) at FIRST / MIDDLE /
    # LAST / NESTED real-array positions, plus the LAST-position family at
    # decode depths 2/3/4: both raw finals reject, the producer masks, the
    # sealed + consumer dual finals accept only the masked output.
    doc_neg = (
        '{"planner_version":["[providerV4]","x","y"]}',
        '{"planner_version":["x","[providerV4]","y"]}',
        '{"planner_version":["x","y","[providerV4]"]}',
        '{"planner_version":["x",["[providerV4]"]]}',
        '{"planner_version":["\\u0070roviderV4","x","y"]}',
        '{"planner_version":["x","\\u0070roviderV4","y"]}',
        '{"planner_version":["x","y","\\u0070roviderV4"]}',
        '{"planner_version":["x",["\\u0070roviderV4"]]}',
        '{"otp":["plannerV2","x","y"]}',
    )
    doc_neg_layered = tuple(
        layered(arr, n)
        for n in (2, 3, 4)
        for arr in (
            '{"planner_version":["x","y","[providerV4]"]}',
            '{"planner_version":["x","y","\\u0070roviderV4"]}',
            '{"otp":["x","y","plannerV2"]}',
        )
    )
    for raw in (*doc_neg, *doc_neg_layered):
        rejects(raw)
        masked = canary._desensitize(raw)
        assert "[REDACTED]" in masked, raw
        assert "providerV4" not in masked, raw
        sealed_accepts(masked, "r42b88n")

    # Block 87 counterexamples preserved verbatim (打回九 要求 3): a genuine
    # ``"[]"`` MEMBER KEY (escaped / unescaped), a pseudo / unbound path and
    # the assignment-helper dotted field never regain the exemption — the
    # first-position fix never treats the STRING key ``'[]'`` as an array
    # marker.
    b87_keep = (
        '{"planner_version":{"[]":"plannerV2"}}',
        '{"planner_version":{"\\u005b\\u005d":"plannerV2"}}',
        '{"summary":{"[]":"plannerV2"}}',
        '{"plan":{"planner_version":{"[]":"plannerV2"}}}',
        '{"evilplanner_version":{"[]":"plannerV2"}}',
        '{"otp":{"[]":"plannerV2"}}',
        "planner_version.[] = plannerV2",
        "plan.planner_version.[] = plannerV2",
        "summary.[] = plannerV2",
        "planner_version.[] = providerV4",
    )
    for raw in b87_keep:
        rejects(raw)
        masked = canary._desensitize(raw)
        assert "[REDACTED]" in masked, raw
        sealed_accepts(masked, "r42b88k")


def test_r42_block89_documented_escaped_key_and_bracket_whitespace_five_route(
    tmp_path: Path,
) -> None:
    r"""C-122 round-42 Block 89 (打回十): two LEGAL-JSON forms were mis-rejected
    by both raw finals while the producer stayed UNTOUCHED and the consumer
    accepted — a five-route asymmetry on inputs the contract exempts.

    (1) ESCAPED DOCUMENTED KEY — a genuine JSON document's member key may carry
    RFC-8259 escape sequences (``{"planner_version":["plannerV2","x"]}``
    where ``_`` decodes to ``_``).  The free-text narration backstop built
    the carried path from the RAW key text, so the decoded key never matched
    the documented registry and the value was rejected.

    (2) BRACKET WHITESPACE — legal JSON whitespace (SPACE/TAB/CR/LF) between
    array openers (``{"planner_version":[ [ "plannerV2" ]] }``) made the regex
    capture the malformed ``[ [ "plannerV2" ]] }`` token (WRAPPED_BASE_ILLEGAL);
    the helper skipped ``[`` and one space but then saw a second ``[`` instead
    of a ``"`` and returned False, so the narration backstop bound.

    The fix decodes the member key exactly like the JSON walker sees it and
    skips ALL legal JSON whitespace between array openers before requiring the
    double-quoted element, so every documented-array element — escaped key and
    each whitespace form, FIRST / MIDDLE / LAST / NESTED, every decode depth
    (real layer plus 2/3/4 ``json.dumps`` encodings) — accepts on all five
    routes with the producer leaving it UNTOUCHED.  The preserved negatives
    (escaped cross-field / unbound / fake-suffix, the real ``"[]"`` member key
    escaped and unescaped, duplicate documented keys, bracket-whitespace
    cross-field / unbound, the dotted assignment-helper with an escaped field)
    still fail closed on both raw finals with the producer masking, and the
    sealed 0600 diagnostic -> consumer dual finals accept ONLY the already-
    masked producer output.
    """
    from benchmarks import live_canary_certified as canary

    def layered(base: str, n: int) -> str:
        s = base
        for _ in range(n):
            s = json.dumps(s)
        return s

    def final(raw: str, label: str, field_check: bool) -> None:
        gate._secret_scan_bytes(
            raw.encode(),
            gate._SecretNeedles(()),
            "evidence",
            label,
            credential_field_check=field_check,
        )

    def rejects(raw: str) -> None:
        with pytest.raises(gate.GateStateChangedError):
            final(raw, "ev.json", True)
        with pytest.raises(gate.GateStateChangedError):
            final(raw, "live-canary-certified.json.failure.json", False)

    def accepts(raw: str) -> None:
        final(raw, "ev.json", True)
        final(raw, "live-canary-certified.json.failure.json", False)

    def sealed_accepts(masked: str, run_id: str) -> None:
        output = tmp_path / "live-canary-certified.json"
        diag = canary._seal_failure_diagnostic(
            "evaluate",
            RuntimeError(masked),
            output,
            run_id=run_id,
            tested_sha="9" * 40,
        )
        assert stat.S_IMODE(diag.stat().st_mode) == 0o600
        gate._secret_scan_bytes(
            diag.read_bytes(),
            gate._SecretNeedles(()),
            "evidence",
            "live-canary-certified.json.failure.json",
            credential_field_check=False,
        )
        gate._secret_scan_bytes(
            gate._sanitize_canary_diag_field(
                json.dumps({"summary": masked}), "fallback"
            ).encode(),
            gate._SecretNeedles(()),
            "evidence",
            "ev.json",
            credential_field_check=True,
        )

    # Block 89 positives — the ESCAPED documented member key (``_`` =
    # ``_``, ``m`` = ``m``) and every legal bracket-whitespace form
    # (SPACE / TAB / CR / LF), FIRST / MIDDLE / LAST / NESTED, for the planner /
    # provider / tokenization / secretariat documented bases, the ``plan.``
    # prefix and the ``summary`` free-text contract: accepted by all five
    # routes, producer-untouched (no ``[REDACTED]``).
    doc_pos = (
        '{"planner\\u005fversion":["plannerV2","x"]}',
        '{"planner\\u005fversion":["x","plannerV2","y"]}',
        '{"planner\\u005fversion":["x","y","plannerV2"]}',
        '{"planner\\u005fversion":[["plannerV2"]]}',
        '{"provider\\u005fversion":["providerV4","x"]}',
        '{"plan":{"planner\\u005fversion":["plannerV2","x"]}}',
        '{"plan":{"tokenization\\u005fversion":["tokenizationV1","x"]}}',
        '{"plan":{"secretariat\\u005fversion":["secretariatV1","x"]}}',
        '{"sum\\u006dary":["plannerV2","x"]}',
        '{"planner_version":[ [ "plannerV2" ]] }',
        '{"planner_version":[\t[\t"plannerV2"\t]]\t}',
        '{"planner_version":[\r\n[\r\n"plannerV2"\r\n]]\r\n}',
        '{"planner_version":[ "plannerV2" ]}',
        '{"planner_version":[ "x", "plannerV2" ]}',
        '{"planner_version":[ "x", "plannerV2", "y" ]}',
        '{"planner_version":[ "x", [ "plannerV2" ] ]}',
        '{"planner_version":[ [ [ "plannerV2" ] ] ]}',
        '{"plan":{"planner_version":[ [ "plannerV2" ]] }}',
        '{"provider_version":[\t[\t"providerV4"\t]]\t}',
        '{"sum\\u006dary":[ [ "plannerV2" ]] }',
    )
    for raw in doc_pos:
        accepts(raw)
        masked = canary._desensitize(raw)
        assert "[REDACTED]" not in masked, raw
        sealed_accepts(masked, "r42b89p")

    # Same escaped-key / whitespace forms re-encoded 2/3/4 times: the path is
    # carried through the decode recursion and the key is decoded at every
    # layer, so each depth accepts and the producer stays untouched.
    doc_pos_layered = tuple(
        layered(arr, n)
        for n in (2, 3, 4)
        for arr in (
            '{"planner\\u005fversion":["plannerV2","x","y"]}',
            '{"planner\\u005fversion":["x",["plannerV2"],"y"]}',
            '{"plan":{"provider\\u005fversion":["providerV4","x"]}}',
            '{"planner_version":[ [ "plannerV2", "x" ]] }',
            '{"planner_version":[\t[\t"plannerV2"\t]]\t}',
            '{"planner_version":[\r\n["plannerV2"]\r\n]}',
        )
    )
    for raw in doc_pos_layered:
        accepts(raw)
        masked = canary._desensitize(raw)
        assert "[REDACTED]" not in masked, raw
        sealed_accepts(masked, "r42b89p")

    # Block 89 negatives — ESCAPED cross-field / unbound / fake-suffix keys,
    # the real ``"[]"`` member key (escaped and unescaped), duplicate
    # documented keys (plain and mixed escaped/raw), bracket-whitespace cross-
    # field / unbound, and the dotted assignment-helper with an ESCAPED field
    # (a non-JSON document, so the escape is never decoded): both raw finals
    # reject, the producer masks, the sealed + consumer dual finals accept only
    # the masked output.
    doc_neg = (
        '{"planner\\u005fversion":["providerV4","x"]}',
        '{"planner\\u005fversion":["x","\\u0070roviderV4","y"]}',
        '{"planner\\u005fversion":["x","y","\\u0070roviderV4"]}',
        '{"ot\\u0070":["plannerV2","x"]}',
        '{"planner_ver\\u0073ionx":["plannerV2","x"]}',
        '{"planner_version":{"\\u005b\\u005d":"plannerV2"}}',
        '{"planner_version":{"[]":"plannerV2"}}',
        '{"planner_version":["plannerV2","x"],"planner_version":["x","plannerV2","y"]}',
        '{"planner\\u005fversion":["plannerV2","x"],"planner_version":["x","plannerV2","y"]}',
        '{"planner_version":[ [ "providerV4" ]] }',
        '{"planner_version":[\t["providerV4"]]}',
        '{"otp":[ [ "plannerV2" ]] }',
        '{"otp":[\r\n["plannerV2"]]}',
        "planner\\u005fversion.[] = plannerV2",
    )
    doc_neg_layered = tuple(
        layered(arr, n)
        for n in (2, 3, 4)
        for arr in (
            '{"planner\\u005fversion":["x","y","\\u0070roviderV4"]}',
            '{"otp":[ [ "plannerV2" ]] }',
            '{"planner_version":{"[]":"plannerV2"}}',
        )
    )
    for raw in (*doc_neg, *doc_neg_layered):
        rejects(raw)
        masked = canary._desensitize(raw)
        assert "[REDACTED]" in masked, raw
        assert "providerV4" not in masked, raw
        sealed_accepts(masked, "r42b89n")



def test_r42_block90_generative_escaped_member_key_matrix(
    tmp_path: Path,
) -> None:
    r"""C-122 round-42 Block 90 (打回十一, matrix 增量): the formal test matrix
    for the leading / full-escaped documented member key must be an AUDITABLE
    GENERATIVE coverage — every Cartesian dimension is enumerated by code and
    the case counts are asserted, so a dropped dimension fails the test instead
    of staying green.

    Root cause (打回十一): a genuine JSON document whose member KEY's FIRST
    character is a backslash-escape (``{"planner_version":
    ["plannerV2","x"]}`` = ``{"planner_version": ...}``) was mis-rejected by
    both raw finals while the producer stayed untouched — the free-text
    assignment regex opens its field with a WORD character, so the capture
    starts AFTER the backslash (field ``u0070lanner_version"``) and the true
    key's leading context is lost; the Block 89 fix only decodes the
    regex-captured field, which can never recover the documented key.  The
    fix resolves the ACTUAL RFC-8259-decoded member key from the REAL
    parsed-JSON quoted span containing the field start (``_json_member_key_at``):
    a span whose closing quote is followed by ``:`` is the member KEY string
    literal and its decoded content is authoritative — the same key the JSON
    walker sees; a VALUE-position span (closing quote followed by anything
    else) returns None and the regex field stays authoritative exactly as
    before.  No reliance on the truncated regex field, global replacement, or
    char-table patching.

    The matrix enumerates every combination of:

    * escape style — LEADING (only the first char escaped) and FULL (every
      char an RFC-8259 ``\uXXXX`` escape);
    * documented key — ``planner_version`` / ``provider_version`` /
      ``summary``;
    * value form — scalar / array-first / array-middle / array-last /
      nested-array / deep-nested;
    * decode depth — the real JSON layer plus 2/3/4 ``json.dumps`` encodings;
    * legal JSON whitespace — SPACE / TAB / CR / LF enumerated independently
      (never a combined CRLF), injected at every structural gap of the array
      brackets and, for the scalar form, at the member colon/value boundary.

    All positive families are enumerated with exact case-count assertions AND
    uniqueness assertions (``len(set(...)) == <count>``, so duplicates cannot
    be padded into a fake dimension), and EVERY positive case — depth 0 AND
    the 2/3/4 encodings — walks the FULL real five-route: raw
    committed/failure dual finals -> producer untouched (``_desensitize`` must
    not over-mask) -> real 0600 O_CREAT|O_EXCL seal
    (``_seal_failure_diagnostic``, mode check) -> consumer dual finals
    (``_sanitize_canary_diag_field`` + committed/failure scans).

    1. Main documented matrix: 2 x 3 x 6 x 4 = 144 unique cases
       (escape style x documented key x value form x depth).
    2. Whitespace matrix: 4 x 2 x 3 x 6 x 4 = 576 unique cases
       (JSON whitespace {SPACE,TAB,CR,LF} x escape style x documented key x
       value form x depth) — every scalar raw carries the actual whitespace at
       its member colon/value boundary, so all 576 raws are distinct.
    3. Escaped parent ``plan`` x escaped child: child is ``planner_version``
       OR ``provider_version``, each child leading/full escaped, parent
       leading/full escaped, depth 0/2/3/4: 2 x 2 x 2 x 4 = 32 unique cases.

    Block 87-90 negatives are preserved with counts (12 real + 12 layered):
    escaped cross-field / unbound / fake-suffix, object-wrapped / real
    ``[]``-key / escaped ``[]``-key, scalar cross-field, duplicate escaped
    key, bracket-whitespace cross-field / fake, and the escaped assignment
    helper dotted form; every raw final rejects and the producer masks.
    """
    from benchmarks import live_canary_certified as canary

    def layered(base: str, n: int) -> str:
        s = base
        for _ in range(n):
            s = json.dumps(s)
        return s

    def final(raw: str, label: str, field_check: bool) -> None:
        gate._secret_scan_bytes(
            raw.encode(),
            gate._SecretNeedles(()),
            "evidence",
            label,
            credential_field_check=field_check,
        )

    def rejects(raw: str) -> None:
        with pytest.raises(gate.GateStateChangedError):
            final(raw, "ev.json", True)
        with pytest.raises(gate.GateStateChangedError):
            final(raw, "live-canary-certified.json.failure.json", False)

    def accepts(raw: str) -> None:
        final(raw, "ev.json", True)
        final(raw, "live-canary-certified.json.failure.json", False)

    def sealed_accepts(masked: str, run_id: str) -> None:
        output = tmp_path / "live-canary-certified.json"
        diag = canary._seal_failure_diagnostic(
            "evaluate",
            RuntimeError(masked),
            output,
            run_id=run_id,
            tested_sha="9" * 40,
        )
        assert stat.S_IMODE(diag.stat().st_mode) == 0o600
        gate._secret_scan_bytes(
            diag.read_bytes(),
            gate._SecretNeedles(()),
            "evidence",
            "live-canary-certified.json.failure.json",
            credential_field_check=False,
        )
        gate._secret_scan_bytes(
            gate._sanitize_canary_diag_field(
                json.dumps({"summary": masked}), "fallback"
            ).encode(),
            gate._SecretNeedles(()),
            "evidence",
            "ev.json",
            credential_field_check=True,
        )

    def full_five_route(raw: str, tag: str) -> None:
        accepts(raw)
        masked = canary._desensitize(raw)
        assert "[REDACTED]" not in masked, raw
        sealed_accepts(masked, tag)

    def esc_leading(key: str) -> str:
        return f"\\u00{ord(key[0]):02x}" + key[1:]

    def esc_full(key: str) -> str:
        return "".join(f"\\u{ord(c):04x}" for c in key)

    def json_with(escaped_key: str, value: str) -> str:
        return '{"' + escaped_key + '":' + value + "}"

    escape_styles = (("leading", esc_leading), ("full", esc_full))
    documented_base = {
        "planner_version": "plannerV2",
        "provider_version": "providerV4",
        "summary": "plannerV2",
    }
    value_forms = {
        "scalar": lambda b: f'"{b}"',
        "array-first": lambda b: f'["{b}","x"]',
        "array-middle": lambda b: f'["x","{b}","y"]',
        "array-last": lambda b: f'["x","y","{b}"]',
        "nested-array": lambda b: f'[["{b}"]]',
        "deep-nested": lambda b: f'[[["{b}"]]]',
    }
    ws_types = (("SPACE", " "), ("TAB", "\t"), ("CR", "\r"), ("LF", "\n"))

    def ws_bracket(ws: str, inner: str) -> str:
        return f"[{ws}{inner}{ws}]"

    ws_value_forms = {
        # scalar injects the whitespace at the member colon/value boundary so
        # each whitespace type yields a distinct raw (never a duplicate).
        "scalar": lambda b, ws: f'{ws}"{b}"{ws}',
        "array-first": lambda b, ws: ws_bracket(ws, f'"{b}"{ws},{ws}"x"'),
        "array-middle": lambda b, ws: ws_bracket(
            ws, f'"x"{ws},{ws}"{b}"{ws},{ws}"y"'
        ),
        "array-last": lambda b, ws: ws_bracket(
            ws, f'"x"{ws},{ws}"y"{ws},{ws}"{b}"'
        ),
        "nested-array": lambda b, ws: ws_bracket(
            ws, ws_bracket(ws, f'"{b}"')
        ),
        "deep-nested": lambda b, ws: ws_bracket(
            ws, ws_bracket(ws, ws_bracket(ws, f'"{b}"'))
        ),
    }

    # --- 1. main documented matrix: esc(2) x key(3) x vf(6) x depth(4) ---
    doc_pos: list[str] = []
    for _en, esc in escape_styles:
        for key in ("planner_version", "provider_version", "summary"):
            for _vn, vf in value_forms.items():
                raw = json_with(esc(key), vf(documented_base[key]))
                doc_pos.append(raw)
                doc_pos.extend(layered(raw, n) for n in (2, 3, 4))
    assert len(doc_pos) == 144, "2 escape styles x 3 keys x 6 value forms x depths"
    assert len(set(doc_pos)) == 144, "main raw cases must be unique"
    for raw in doc_pos:
        full_five_route(raw, "r42b90m")

    # --- 2. whitespace matrix: ws(4) x esc(2) x key(3) x vf(6) x depth(4) ---
    ws_pos: list[str] = []
    for _wn, ws in ws_types:
        for _en, esc in escape_styles:
            for key in ("planner_version", "provider_version", "summary"):
                for _vn, vf in ws_value_forms.items():
                    raw = json_with(esc(key), vf(documented_base[key], ws))
                    ws_pos.append(raw)
                    ws_pos.extend(layered(raw, n) for n in (2, 3, 4))
    assert len(ws_pos) == 576, "4 ws{SPACE,TAB,CR,LF} x 2 esc x 3 keys x 6 vf x 4 depths"
    assert len(set(ws_pos)) == 576, "ws raw cases must be unique per whitespace type"
    for raw in ws_pos:
        full_five_route(raw, "r42b90w")

    # --- 3. escaped plan parent x escaped child (planner_version / provider_version) ---
    plan_pos: list[str] = []
    for _pn, parent in (("leading", esc_leading("plan")), ("full", esc_full("plan"))):
        for child_key in ("planner_version", "provider_version"):
            for _cn, child in (
                ("leading", esc_leading(child_key)),
                ("full", esc_full(child_key)),
            ):
                raw = f'{{"{parent}":{{"{child}":["{documented_base[child_key]}","x"]}}}}'
                plan_pos.append(raw)
                plan_pos.extend(layered(raw, n) for n in (2, 3, 4))
    assert len(plan_pos) == 32, "2 parent esc x 2 child keys x 2 child esc x 4 depths"
    assert len(set(plan_pos)) == 32, "plan raw cases must be unique"
    for raw in plan_pos:
        full_five_route(raw, "r42b90p")

    # --- Block 87-90 negatives preserved (count-asserted) ---
    doc_neg = (
        '{"\\u0070lanner_version":["providerV4","x"]}',
        '{"\\u0070lanner_version":["\\u0070roviderV4","x"]}',
        '{"\\u0070\\u006c\\u0061\\u006e\\u006e\\u0065\\u0072\\u005f\\u0076\\u0065\\u0072\\u0073\\u0069\\u006f\\u006e":["providerV4","x"]}',
        '{"\\u0070tp":["plannerV2","x"]}',
        '{"\\u0070lanner_versionx":["plannerV2","x"]}',
        '{"\\u0070lanner_version":{"[]":"plannerV2"}}',
        '{"\\u0070lanner_version":{"\\u005b\\u005d":"plannerV2"}}',
        '{"\\u0070lanner_version":"providerV4"}',
        '{"\\u0070lanner_version":["plannerV2","x"],"\\u0070lanner_version":["x","plannerV2","y"]}',
        '{"\\u0070lanner_version":[ [ "providerV4" ]] }',
        '{"\\u0070tp":[ [ "plannerV2" ]] }',
        "\\u0070lanner_version.[] = plannerV2",
    )
    doc_neg_layered = tuple(
        layered(arr, n)
        for n in (2, 3, 4)
        for arr in (
            '{"\\u0070lanner_version":["x","\\u0070roviderV4","y"]}',
            '{"\\u0070tp":["plannerV2","x"]}',
            '{"\\u0070lanner_version":{"[]":"plannerV2"}}',
            '{"\\u0070lanner_version":[ [ "providerV4" ]] }',
        )
    )
    assert len(doc_neg) == 12, "negatives: [] key/cross-field/unbound/fake/dot/dup"
    assert len(doc_neg_layered) == 12, "4 negative bases x depths {2,3,4}"
    for raw in (*doc_neg, *doc_neg_layered):
        rejects(raw)
        masked = canary._desensitize(raw)
        assert "[REDACTED]" in masked, raw
        assert "providerV4" not in masked, raw
        sealed_accepts(masked, "r42b90n")
